// BCFA deploy (Phase 12+): records from the now-sdk build output, upserted
// by build sys_id. Generated by scripts/deploy/gen_record_loader.mjs. Run in
// Scripts - Background with scope = global. Safe to re-run.
var files = [{"name":"sys_script_include_5557c39b046b40dbb32c511181f09e80.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>5557c39b046b40dbb32c511181f09e80</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_5557c39b046b40dbb32c511181f09e80</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.DemoDataSeeder</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Demo data: master data (vendors, customers, POs, receipts, AR open items, credit notes) plus the 10 named AP and 10 named AR scenarios; resetDemoData / resetAndReseed put the data back to that baseline (Phase 28).</description>\n    <mobile_callable>false</mobile_callable>\n    <name>DemoDataSeeder</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[// Stage 10/17 demo data. Deliberately scaled down from the brief's suggested\r\n// volumes (10 vendors/10 customers kept as-is; POs/receipts/open-items\r\n// reduced) because the 10 named AP/AR scenarios — the actual acceptance\r\n// criteria — need specific, deliberately-crafted supporting data more than\r\n// they need raw volume. See docs/BUILD_REPORT.md for this scope note.\r\n//\r\n// Run once via an ATF runServerSideScript step (see tests/) — there is no\r\n// other script-execution surface available to this build.\r\nvar DemoDataSeeder = Class.create();\r\nDemoDataSeeder.prototype = {\r\n    initialize: function() {\r\n        this.apService = new ApDomainService();\r\n        this.arService = new ArDomainService();\r\n    },\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedAll: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedAll(); });\r\n    },\r\n\r\n    _seedAll: function() {\r\n        // Phase 28: master data is upserted whenever the AP scenarios are\r\n        // absent (first seed, or after resetDemoData), so the scenarios start\r\n        // from the seeded baseline.\r\n        var scenariosPresent = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        scenariosPresent.addQuery('invoice_number', 'INV-AP-001');\r\n        scenariosPresent.query();\r\n        var masterData = scenariosPresent.hasNext() ? { skipped: true } : this.seedMasterData();\r\n\r\n        // AP/AR scenarios use fixed, deterministic keys (INV-AP-001,\r\n        // BANK-AR-001, ...) by design, so re-running this against an instance\r\n        // that already has them would trip the seeder's own duplicate/\r\n        // idempotency detection against its *own* prior output. Guard the\r\n        // same way seedMasterData() already does.\r\n        var apAlreadySeeded = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        apAlreadySeeded.addQuery('invoice_number', 'INV-AP-001');\r\n        apAlreadySeeded.query();\r\n        var apResults = apAlreadySeeded.next() ? { skipped: true } : this.seedApScenarios();\r\n\r\n        var arAlreadySeeded = new GlideRecord('x_695068_bcfa_payment');\r\n        arAlreadySeeded.addQuery('bank_reference', 'BANK-AR-001');\r\n        arAlreadySeeded.query();\r\n        var arResults = arAlreadySeeded.next() ? { skipped: true } : this.seedArScenarios();\r\n\r\n        return { masterData: masterData, apScenarios: apResults, arScenarios: arResults };\r\n    },\r\n\r\n    // [requester, approver]. Phase 17: approvals pass the segregation-of-\r\n    // duties gate (approver role, not the requester, not the processor, in\r\n    // the approval group), so the demo processor requests and the demo\r\n    // finance approver approves when those users exist.\r\n    _twoUsers: function() {\r\n        var processor = this._lookupSysId('sys_user', 'user_name', 'bcfa.ap.processor');\r\n        var approver = this._lookupSysId('sys_user', 'user_name', 'bcfa.finance.approver');\r\n        if (processor && approver) return [processor, approver];\r\n        var users = [];\r\n        var gr = new GlideRecord('sys_user');\r\n        gr.addQuery('active', true);\r\n        gr.orderBy('sys_created_on');\r\n        gr.setLimit(5);\r\n        gr.query();\r\n        while (gr.next() && users.length < 2) {\r\n            users.push(gr.getUniqueValue());\r\n        }\r\n        if (users.length === 0) users.push(gs.getUserID());\r\n        if (users.length === 1) users.push(users[0]);\r\n        return users;\r\n    },\r\n\r\n    // Updates the row matching all key fields, or inserts one. Returns sys_id.\r\n    _upsert: function(table, keys, fields) {\r\n        var gr = new GlideRecord(table);\r\n        for (var k in keys) gr.addQuery(k, keys[k]);\r\n        gr.setLimit(1);\r\n        gr.query();\r\n        if (!gr.next()) return this._insert(table, fields);\r\n        for (var key in fields) gr.setValue(key, fields[key]);\r\n        gr.update();\r\n        return gr.getUniqueValue();\r\n    },\r\n\r\n    _insert: function(table, fields) {\r\n        var gr = new GlideRecord(table);\r\n        gr.initialize();\r\n        for (var key in fields) {\r\n            gr.setValue(key, fields[key]);\r\n        }\r\n        return gr.insert();\r\n    },\r\n\r\n    // Phase 28: upserts by business key (vendor code, PO number, item number,\r\n    // ...). Existing rows keep their sys_id (reference mappings point at\r\n    // them) and get their seeded values back, e.g. an open item's open amount\r\n    // after a clearing consumed it.\r\n    seedMasterData: function() {\r\n        var vendorDefs = [\r\n            { vendor_code: 'V001', name: 'Rajasthan Carbon Feedstock Pvt Ltd', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0001' },\r\n            { vendor_code: 'V002', name: 'Gujarat Oil Traders Ltd', country: 'India', currency: 'INR', payment_terms: 'NET45', bank_account: 'IN-ACC-0002' },\r\n            { vendor_code: 'V003', name: 'Budapest Chemicals Kft', country: 'Hungary', currency: 'EUR', payment_terms: 'NET30', bank_account: 'HU-ACC-0003' },\r\n            { vendor_code: 'V004', name: 'Rhine Logistics GmbH', country: 'Germany', currency: 'EUR', payment_terms: 'NET30', bank_account: 'DE-ACC-0004' },\r\n            { vendor_code: 'V005', name: 'Gulf Coast Feedstock LLC', country: 'United States', currency: 'USD', payment_terms: 'NET60', bank_account: 'US-ACC-0005' },\r\n            { vendor_code: 'V006', name: 'Chennai Packaging Solutions', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0006' },\r\n            { vendor_code: 'V007', name: 'Miskolc Freight Services', country: 'Hungary', currency: 'EUR', payment_terms: 'NET15', bank_account: 'HU-ACC-0007' },\r\n            { vendor_code: 'V008', name: 'Bavaria Industrial Supplies AG', country: 'Germany', currency: 'EUR', payment_terms: 'NET30', bank_account: 'DE-ACC-0008' },\r\n            { vendor_code: 'V009', name: 'Texas Carbon Feedstock Inc', country: 'United States', currency: 'USD', payment_terms: 'NET45', bank_account: 'US-ACC-0009' },\r\n            { vendor_code: 'V010', name: 'Odisha Raw Materials Pvt Ltd', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0010' }\r\n        ];\r\n        var vendorSysId = {};\r\n        for (var v = 0; v < vendorDefs.length; v++) {\r\n            var def = vendorDefs[v];\r\n            def.active = true;\r\n            vendorSysId[def.vendor_code] = this._upsert('x_695068_bcfa_vendor', { vendor_code: def.vendor_code }, def);\r\n        }\r\n\r\n        var customerDefs = [\r\n            { customer_code: 'C001', name: 'Continental Tyre Manufacturing', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C002', name: 'Deccan Rubber Industries', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C003', name: 'Pannonia Polymer Zrt', country: 'Hungary', currency: 'EUR' },\r\n            { customer_code: 'C004', name: 'Schwarzwald Elastomers GmbH', country: 'Germany', currency: 'EUR' },\r\n            { customer_code: 'C005', name: 'Lone Star Tyre Corp', country: 'United States', currency: 'USD' },\r\n            { customer_code: 'C006', name: 'Bengal Compounds Ltd', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C007', name: 'Danube Rubber Kft', country: 'Hungary', currency: 'EUR' },\r\n            { customer_code: 'C008', name: 'Ruhr Valley Polymers AG', country: 'Germany', currency: 'EUR' },\r\n            { customer_code: 'C009', name: 'Pacific Coast Tyre Co', country: 'United States', currency: 'USD' },\r\n            { customer_code: 'C010', name: 'Karnataka Elastomers Pvt Ltd', country: 'India', currency: 'INR' }\r\n        ];\r\n        var customerSysId = {};\r\n        for (var c = 0; c < customerDefs.length; c++) {\r\n            var cdef = customerDefs[c];\r\n            cdef.active = true;\r\n            customerSysId[cdef.customer_code] = this._upsert('x_695068_bcfa_customer', { customer_code: cdef.customer_code }, cdef);\r\n        }\r\n        var customerCurrency = {};\r\n        for (var cc = 0; cc < customerDefs.length; cc++) customerCurrency[customerDefs[cc].customer_code] = customerDefs[cc].currency;\r\n\r\n        // Purchase orders + lines. Each entry describes one PO with one line.\r\n        var poDefs = [\r\n            { po: 'PO0001', vendorCode: 'V001', qty: 100, unitPrice: 50, unit: 'MT' },\r\n            { po: 'PO0002', vendorCode: 'V002', qty: 200, unitPrice: 30, unit: 'MT' },\r\n            { po: 'PO0003', vendorCode: 'V003', qty: 50, unitPrice: 120, unit: 'MT' },\r\n            { po: 'PO0004', vendorCode: 'V004', qty: 10, unitPrice: 500, unit: 'EA' },\r\n            { po: 'PO0005', vendorCode: 'V005', qty: 300, unitPrice: 40, unit: 'MT' },\r\n            { po: 'PO0006', vendorCode: 'V006', qty: 1000, unitPrice: 2, unit: 'EA' },\r\n            { po: 'PO0007', vendorCode: 'V007', qty: 20, unitPrice: 250, unit: 'EA' },\r\n            { po: 'PO0008', vendorCode: 'V008', qty: 75, unitPrice: 80, unit: 'MT' },\r\n            { po: 'PO0009', vendorCode: 'V009', qty: 150, unitPrice: 45, unit: 'MT' },\r\n            { po: 'PO0010', vendorCode: 'V010', qty: 90, unitPrice: 60, unit: 'MT' }\r\n        ];\r\n        var poLineSysId = {};\r\n        var poSysId = {};\r\n        for (var p = 0; p < poDefs.length; p++) {\r\n            var pdef = poDefs[p];\r\n            var poId = this._upsert('x_695068_bcfa_purchase_order', { po_number: pdef.po }, {\r\n                po_number: pdef.po, vendor: vendorSysId[pdef.vendorCode], company_code: '1000',\r\n                currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n            });\r\n            poSysId[pdef.po] = poId;\r\n            poLineSysId[pdef.po] = this._upsert('x_695068_bcfa_po_line', { purchase_order: poId, line_number: 1 }, {\r\n                purchase_order: poId, line_number: 1, material_or_service: 'Carbon black feedstock',\r\n                quantity: pdef.qty, unit: pdef.unit, unit_price: pdef.unitPrice, received_quantity: pdef.qty\r\n            });\r\n        }\r\n\r\n        // Receipts: most match their PO line exactly; RCPT0004 and RCPT0005\r\n        // are deliberately off to support AP-004/AP-005.\r\n        var receiptDefs = [\r\n            { receipt: 'RCPT0001', po: 'PO0001', qty: 100 },\r\n            { receipt: 'RCPT0002', po: 'PO0002', qty: 200 },\r\n            { receipt: 'RCPT0003', po: 'PO0003', qty: 50 },\r\n            { receipt: 'RCPT0004', po: 'PO0004', qty: 10 },\r\n            { receipt: 'RCPT0005', po: 'PO0005', qty: 300 },\r\n            { receipt: 'RCPT0006', po: 'PO0006', qty: 1000 },\r\n            { receipt: 'RCPT0007', po: 'PO0007', qty: 20 },\r\n            { receipt: 'RCPT0008', po: 'PO0008', qty: 75 },\r\n            { receipt: 'RCPT0009', po: 'PO0009', qty: 150 },\r\n            { receipt: 'RCPT0010', po: 'PO0010', qty: 90 }\r\n        ];\r\n        var receiptSysId = {};\r\n        for (var r = 0; r < receiptDefs.length; r++) {\r\n            var rdef = receiptDefs[r];\r\n            receiptSysId[rdef.receipt] = this._upsert('x_695068_bcfa_receipt', { receipt_number: rdef.receipt }, {\r\n                receipt_number: rdef.receipt, po_line: poLineSysId[rdef.po], receipt_type: 'grn',\r\n                quantity: rdef.qty, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO' + rdef.receipt\r\n            });\r\n        }\r\n\r\n        // AR open items spread across customers for exact/multi/partial match testing.\r\n        var itemDefs = [\r\n            { item: 'ARI0001', customerCode: 'C001', amount: 15000 },\r\n            { item: 'ARI0002', customerCode: 'C002', amount: 8000 },\r\n            { item: 'ARI0003', customerCode: 'C002', amount: 12000 },\r\n            { item: 'ARI0004', customerCode: 'C002', amount: 5000 },\r\n            { item: 'ARI0005', customerCode: 'C003', amount: 22000 },\r\n            { item: 'ARI0006', customerCode: 'C004', amount: 9500 },\r\n            { item: 'ARI0007', customerCode: 'C005', amount: 30000 },\r\n            { item: 'ARI0008', customerCode: 'C006', amount: 4200 },\r\n            { item: 'ARI0009', customerCode: 'C007', amount: 17500 },\r\n            { item: 'ARI0010', customerCode: 'C008', amount: 6800 },\r\n            { item: 'ARI0011', customerCode: 'C009', amount: 25000 },\r\n            { item: 'ARI0012', customerCode: 'C010', amount: 11000 },\r\n            { item: 'ARI0013', customerCode: 'C001', amount: 3000 },\r\n            { item: 'ARI0014', customerCode: 'C003', amount: 7000 },\r\n            { item: 'ARI0015', customerCode: 'C009', amount: 5500 }\r\n        ];\r\n        var itemSysId = {};\r\n        for (var i = 0; i < itemDefs.length; i++) {\r\n            var idef = itemDefs[i];\r\n            // Stagger due dates by index rather than stamping every item with\r\n            // today's date — multiInvoiceSuggestion orders by due_date\r\n            // (\"oldest first\"), and identical dates made that ordering\r\n            // meaningless (effectively arbitrary/insertion-order), which is\r\n            // what let AR-008's fuzzy match silently grab C001's much larger\r\n            // ARI0001 instead of the small ARI0013 the credit-note-netting\r\n            // demo actually needs.\r\n            var dueDate = new GlideDateTime();\r\n            dueDate.addDaysUTC(-i);\r\n            itemSysId[idef.item] = this._upsert('x_695068_bcfa_ar_open_item', { item_number: idef.item }, {\r\n                item_number: idef.item, customer: customerSysId[idef.customerCode], company_code: '1000',\r\n                // Phase 14: the item currency follows the customer (was always\r\n                // INR, which let EUR/USD payments match INR items).\r\n                currency: customerCurrency[idef.customerCode], invoice_amount: idef.amount, open_amount: idef.amount,\r\n                due_date: dueDate.getDate(), status: 'open'\r\n            });\r\n        }\r\n\r\n        var creditNoteDefs = [\r\n            { cn: 'CN0001', customerCode: 'C001', amount: 1000 },\r\n            { cn: 'CN0002', customerCode: 'C002', amount: 500 },\r\n            { cn: 'CN0003', customerCode: 'C005', amount: 2000 },\r\n            { cn: 'CN0004', customerCode: 'C007', amount: 750 },\r\n            { cn: 'CN0005', customerCode: 'C009', amount: 1200 }\r\n        ];\r\n        for (var n = 0; n < creditNoteDefs.length; n++) {\r\n            var ndef = creditNoteDefs[n];\r\n            this._upsert('x_695068_bcfa_credit_note', { credit_note_number: ndef.cn }, {\r\n                credit_note_number: ndef.cn, customer: customerSysId[ndef.customerCode],\r\n                amount: ndef.amount, open_amount: ndef.amount, issue_date: new GlideDateTime().getDate(), status: 'open'\r\n            });\r\n        }\r\n\r\n        // Customer alias for AR-004.\r\n        this._upsert('x_695068_bcfa_customer_alias', { alias_name: 'LONE STAR TYRE CO' }, {\r\n            customer: customerSysId['C005'], alias_name: 'LONE STAR TYRE CO', alias_type: 'bank_remitter_name', confidence: 0.9, active: true\r\n        });\r\n\r\n        // Integration Profiles (Section 9) — all default to success; Stage 12\r\n        // resilience tests flip these temporarily.\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock SAP - Default' }, { name: 'Mock SAP - Default', adapter: 'mock_sap', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock Bank - Default' }, { name: 'Mock Bank - Default', adapter: 'mock_bank', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock Archive - Default' }, { name: 'Mock Archive - Default', adapter: 'mock_archive', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n\r\n        this._vendorSysId = vendorSysId;\r\n        this._customerSysId = customerSysId;\r\n        this._poSysId = poSysId;\r\n        this._poLineSysId = poLineSysId;\r\n        this._receiptSysId = receiptSysId;\r\n        this._itemSysId = itemSysId;\r\n\r\n        return {\r\n            vendors: vendorDefs.length, customers: customerDefs.length, purchaseOrders: poDefs.length,\r\n            receipts: receiptDefs.length, arOpenItems: itemDefs.length, creditNotes: creditNoteDefs.length\r\n        };\r\n    },\r\n\r\n    _lookupSysId: function(table, field, value) {\r\n        var gr = new GlideRecord(table);\r\n        if (gr.get(field, value)) return gr.getUniqueValue();\r\n        return null;\r\n    },\r\n\r\n    // The approval cascade Business Rules (ApInvoiceApprovalCascade /\r\n    // ArPaymentApprovalCascade) always auto-post/auto-clear synchronously on\r\n    // approval using the *active* Integration Profile's failure_mode — they\r\n    // never see a per-call simulateOutcome. To demo a specific SAP outcome\r\n    // (AP-009/AP-010/AR-010) the profile itself must be flipped immediately\r\n    // before the approval call and restored immediately after, rather than\r\n    // making a second explicit postInvoice()/clearPayment() call afterward —\r\n    // that second call would just replay the cascade's own already-successful\r\n    // result via the idempotency cache and never actually simulate anything.\r\n    _setAdapterFailureMode: function(adapter, mode) {\r\n        var gr = new GlideRecord('x_695068_bcfa_integration_profile');\r\n        gr.addQuery('adapter', adapter);\r\n        gr.addQuery('active', true);\r\n        gr.query();\r\n        while (gr.next()) {\r\n            gr.setValue('failure_mode', mode);\r\n            gr.update();\r\n        }\r\n    },\r\n\r\n    _latestIntegrationTxn: function(sourceTable, sourceRecord, operation) {\r\n        var gr = new GlideRecord('x_695068_bcfa_integration_txn');\r\n        gr.addQuery('source_table', sourceTable);\r\n        gr.addQuery('source_record', sourceRecord);\r\n        gr.addQuery('operation', operation);\r\n        gr.orderByDesc('sys_created_on');\r\n        gr.setLimit(1);\r\n        gr.query();\r\n        return gr.next() ? gr.getUniqueValue() : null;\r\n    },\r\n\r\n    // ---- AP scenarios (Section 17/19) ---------------------------------------\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedApScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedApScenarios(); });\r\n    },\r\n\r\n    _seedApScenarios: function() {\r\n        var users = this._twoUsers();\r\n        var requester = users[0];\r\n        var approver = users[1];\r\n        var results = {};\r\n\r\n        // AP-001 Happy path: full lifecycle through CLOSED.\r\n        var ap001 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-001', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0001'),\r\n            grossAmount: 5000, taxAmount: 900, netAmount: 5000,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-001', vendor: 'V001', amount: 5000 },\r\n            lines: [this._seedLine('PO0001', 'RCPT0001', 100, 50, 900, 5000)]\r\n        });\r\n        results['AP-001'] = ap001;\r\n        if (ap001.stoppedAt === 'MATCHED') {\r\n            var ap001Approval = this.apService.requestApproval(ap001.apInvoiceSysId, requester);\r\n            this.apService.decideApproval(ap001.apInvoiceSysId, ap001Approval.approvalSysId, 'approved', approver, 'Approved for demo AP-001 happy path.');\r\n        }\r\n\r\n        // AP-002 Duplicate invoice: same vendor/invoice_number/amount as AP-001.\r\n        var ap002 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-001', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001'),\r\n            companyCode: '1000', currency: 'INR', grossAmount: 5000, netAmount: 5000, taxAmount: 900,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-001', vendor: 'V001', amount: 5000 }\r\n        });\r\n        results['AP-002'] = ap002;\r\n\r\n        // AP-003 PO mismatch: purchase_order left unset intentionally, but the\r\n        // invoice text implies one was expected — validateInvoice does not\r\n        // fail on a missing PO by itself, so we simulate the mismatch by\r\n        // pointing at a PO line that does not belong to any PO record.\r\n        var ap003 = this.apService.intakeInvoice({\r\n            invoiceNumber: 'INV-AP-003', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V002'),\r\n            companyCode: '1000', currency: 'INR', grossAmount: 6000, netAmount: 6000, taxAmount: 1080\r\n        });\r\n        this.apService.runExtraction(ap003.apInvoiceSysId, { invoiceNumber: 'INV-AP-003' });\r\n        var invoice003 = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        invoice003.get(ap003.apInvoiceSysId);\r\n        invoice003.setValue('purchase_order', gs.generateGUID());\r\n        invoice003.update();\r\n        results['AP-003'] = this.apService.validateInvoice(ap003.apInvoiceSysId);\r\n\r\n        // AP-004 Quantity tolerance failure: line quantity far exceeds receipt.\r\n        var ap004 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-004', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V004'),\r\n            companyCode: '1000', currency: 'EUR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0004'),\r\n            grossAmount: 5000, netAmount: 5000, taxAmount: 950,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-004' },\r\n            lines: [this._seedLine('PO0004', 'RCPT0004', 15, 500, 950, 5000)]\r\n        });\r\n        results['AP-004'] = ap004;\r\n\r\n        // AP-005 Price tolerance failure: unit price far above PO price.\r\n        var ap005 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-005', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V005'),\r\n            companyCode: '1000', currency: 'USD', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0005'),\r\n            grossAmount: 15000, netAmount: 15000, taxAmount: 0,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-005' },\r\n            lines: [this._seedLine('PO0005', 'RCPT0005', 300, 50, 0, 15000)]\r\n        });\r\n        results['AP-005'] = ap005;\r\n\r\n        // AP-006 Tax validation failure: India vendor, tax far off 18%.\r\n        var ap006 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-006', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V006'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0006'),\r\n            grossAmount: 2100, netAmount: 2000, taxAmount: 50,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-006' },\r\n            lines: [this._seedLine('PO0006', 'RCPT0006', 1000, 2, 50, 2000)]\r\n        });\r\n        results['AP-006'] = ap006;\r\n\r\n        // AP-007 Low-confidence extraction.\r\n        var ap007 = this.apService.intakeInvoice({\r\n            invoiceNumber: 'INV-AP-007', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V007'),\r\n            companyCode: '1000', currency: 'EUR', grossAmount: 3000, netAmount: 3000, taxAmount: 0\r\n        });\r\n        this.apService.runExtraction(ap007.apInvoiceSysId, { invoiceNumber: 'INV-AP-007' }, { forceConfidence: 0.5 });\r\n        results['AP-007'] = this.apService.validateInvoice(ap007.apInvoiceSysId);\r\n\r\n        // AP-008 Approval required: matched, left pending for a human.\r\n        var ap008 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-008', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V008'),\r\n            companyCode: '1000', currency: 'EUR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0008'),\r\n            grossAmount: 6000, netAmount: 6000, taxAmount: 1140,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-008' },\r\n            lines: [this._seedLine('PO0008', 'RCPT0008', 75, 80, 1140, 6000)]\r\n        });\r\n        if (ap008.stoppedAt === 'MATCHED') this.apService.requestApproval(ap008.apInvoiceSysId, requester);\r\n        results['AP-008'] = ap008;\r\n\r\n        // AP-009 SAP posting failure.\r\n        var ap009 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-009', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V009'),\r\n            companyCode: '1000', currency: 'USD', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0009'),\r\n            grossAmount: 6750, netAmount: 6750, taxAmount: 0,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-009' },\r\n            lines: [this._seedLine('PO0009', 'RCPT0009', 150, 45, 0, 6750)]\r\n        });\r\n        if (ap009.stoppedAt === 'MATCHED') {\r\n            var ap009Approval = this.apService.requestApproval(ap009.apInvoiceSysId, requester);\r\n            this._setAdapterFailureMode('mock_sap', 'technical_error');\r\n            this.apService.decideApproval(ap009.apInvoiceSysId, ap009Approval.approvalSysId, 'approved', approver, 'Approved — will fail at SAP for demo AP-009.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ap009Invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n            ap009Invoice.get(ap009.apInvoiceSysId);\r\n            results['AP-009'] = {\r\n                posted: false,\r\n                failed: ap009Invoice.getValue('posting_state') === 'failed',\r\n                postingState: ap009Invoice.getValue('posting_state'),\r\n                state: ap009Invoice.getValue('state')\r\n            };\r\n        } else {\r\n            results['AP-009'] = { error: 'match failed unexpectedly', detail: ap009 };\r\n        }\r\n\r\n        // AP-010 SAP timeout -> Unknown Outcome -> reconciled to POSTED (Demo 3).\r\n        // taxAmount is 18% of netAmount (India vendor rate, see\r\n        // docs/BUSINESS_RULES.md's country tax table) — an earlier version of\r\n        // this scenario hardcoded taxAmount: 0, which itself failed tax\r\n        // validation before ever reaching the posting step this scenario is\r\n        // meant to demonstrate.\r\n        var ap010 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-010', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V010'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0010'),\r\n            grossAmount: 6372, netAmount: 5400, taxAmount: 972,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-010' },\r\n            lines: [this._seedLine('PO0010', 'RCPT0010', 90, 60, 972, 5400)]\r\n        });\r\n        if (ap010.stoppedAt === 'MATCHED') {\r\n            var ap010Approval = this.apService.requestApproval(ap010.apInvoiceSysId, requester);\r\n            this._setAdapterFailureMode('mock_sap', 'timeout');\r\n            this.apService.decideApproval(ap010.apInvoiceSysId, ap010Approval.approvalSysId, 'approved', approver, 'Approved — will time out for demo AP-010.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ap010TxnSysId = this._latestIntegrationTxn('x_695068_bcfa_ap_invoice', ap010.apInvoiceSysId, 'postVendorInvoice');\r\n            results['AP-010'] = { transactionSysId: ap010TxnSysId };\r\n            if (ap010TxnSysId) {\r\n                results['AP-010'].reconciliation = this.apService.reconcilePosting(ap010.apInvoiceSysId, ap010TxnSysId);\r\n            }\r\n        } else {\r\n            results['AP-010'] = { error: 'match failed unexpectedly', detail: ap010 };\r\n        }\r\n\r\n        return results;\r\n    },\r\n\r\n    // Invoice line in ApDomainService.attachInvoiceLine field shape, linked\r\n    // to the PO's (single) line and the given receipt. Phase 14: lines are\r\n    // attached at intake so the 3-way match sees them (a PO invoice without\r\n    // linked, received lines now fails matching).\r\n    _seedLine: function(poNumber, receiptNumber, quantity, unitPrice, tax, amount) {\r\n        return {\r\n            lineNumber: 1, materialOrService: 'Carbon black feedstock', quantity: quantity, unit: 'MT', unitPrice: unitPrice, tax: tax, amount: amount,\r\n            poLine: this._lookupSysId('x_695068_bcfa_po_line', 'purchase_order', this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', poNumber)),\r\n            receiptReference: this._lookupSysId('x_695068_bcfa_receipt', 'receipt_number', receiptNumber)\r\n        };\r\n    },\r\n\r\n    // ---- AR scenarios (Section 17/19) ---------------------------------------\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedArScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedArScenarios(); });\r\n    },\r\n\r\n    _seedArScenarios: function() {\r\n        var users = this._twoUsers();\r\n        var requester = users[0];\r\n        var approver = users[1];\r\n        var results = {};\r\n\r\n        // AR-001 Exact match: payment equals ARI0001's open amount exactly.\r\n        var ar001 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-001', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001'),\r\n            currency: 'INR', amount: 15000, bankAccount: 'IN-COLL-001',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-001'\r\n        });\r\n        results['AR-001'] = ar001;\r\n        if (ar001.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar001Approval = this.arService.requestApproval(ar001.paymentSysId, requester);\r\n            this.arService.decideApproval(ar001.paymentSysId, ar001Approval.approvalSysId, 'approved', approver, 'Approved for demo AR-001.');\r\n        }\r\n\r\n        // AR-002 Partial payment: less than ARI0006's open amount, only\r\n        // candidate available for that customer.\r\n        var ar002 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-002', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C004'),\r\n            currency: 'EUR', amount: 6000, bankAccount: 'DE-COLL-002',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-002'\r\n        });\r\n        results['AR-002'] = ar002;\r\n\r\n        // AR-003 Multi-invoice allocation: sum of ARI0002+ARI0003+ARI0004 = 25000.\r\n        var ar003 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-003', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C002'),\r\n            currency: 'INR', amount: 25000, bankAccount: 'IN-COLL-003',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-003'\r\n        });\r\n        results['AR-003'] = ar003;\r\n        if (ar003.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar003Approval = this.arService.requestApproval(ar003.paymentSysId, requester);\r\n            this.arService.decideApproval(ar003.paymentSysId, ar003Approval.approvalSysId, 'approved', approver, 'Approved for demo AR-003.');\r\n        }\r\n\r\n        // AR-004 Customer alias: customer left unset, resolved via alias.\r\n        var ar004 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-004', currency: 'USD', amount: 30000, bankAccount: 'US-COLL-004',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-004', candidateCustomerName: 'LONE STAR TYRE CO'\r\n        });\r\n        results['AR-004'] = ar004;\r\n\r\n        // AR-005 Unmatched payment: customer with no open items (C010 already\r\n        // has ARI0012, so pick an amount nothing sums to and no candidate\r\n        // customer at all).\r\n        var ar005 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-005', currency: 'INR', amount: 99999, bankAccount: 'IN-COLL-005',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-005', candidateCustomerName: 'UNKNOWN REMITTER XYZ'\r\n        });\r\n        results['AR-005'] = ar005;\r\n\r\n        // AR-006 Short pay: less than ARI0009's open amount.\r\n        var ar006 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-006', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C007'),\r\n            currency: 'EUR', amount: 15000, bankAccount: 'HU-COLL-006',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-006'\r\n        });\r\n        results['AR-006'] = ar006;\r\n        if (ar006.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            this.arService.exceptionEngine.resolveArException(ar006.detail.exceptionSysId, 'Confirmed with customer: intentional short-pay pending credit memo. Approved to proceed as-is for demo.', requester);\r\n            this.arService.forceProceedDespiteImbalance(ar006.paymentSysId, 'Manager override: proceeding despite confirmed short-pay — demo AR-006.');\r\n        }\r\n\r\n        // AR-007 Bank charge: payment is open_amount minus a small bank\r\n        // charge — flagged as short_pay, then a reviewer records the\r\n        // deduction (see docs/BUSINESS_RULES.md limitation note on\r\n        // auto-classifying deductions).\r\n        var ar007 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-007', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C010'),\r\n            currency: 'INR', amount: 10975, bankAccount: 'IN-COLL-007',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-007'\r\n        });\r\n        results['AR-007'] = ar007;\r\n        if (ar007.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            var allocation007 = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n            allocation007.addQuery('payment', ar007.paymentSysId);\r\n            allocation007.query();\r\n            if (allocation007.next()) {\r\n                this._insert('x_695068_bcfa_deduction', { payment_allocation: allocation007.getUniqueValue(), deduction_type: 'bank_charge', amount: 25, status: 'approved', notes: 'Bank charge identified during review — demo AR-007.' });\r\n            }\r\n            this.arService.exceptionEngine.resolveArException(ar007.detail.exceptionSysId, 'Bank charge of 25 identified and recorded as a deduction.', requester);\r\n            this.arService.advanceAfterDeduction(ar007.paymentSysId);\r\n        }\r\n\r\n        // AR-008 Credit note netting: payment short by the amount of CN0001.\r\n        var ar008 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-008', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001'),\r\n            currency: 'INR', amount: 2000, bankAccount: 'IN-COLL-008',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-008'\r\n        });\r\n        results['AR-008'] = ar008;\r\n        if (ar008.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            var allocation008 = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n            allocation008.addQuery('payment', ar008.paymentSysId);\r\n            allocation008.query();\r\n            var creditNote001 = this._lookupSysId('x_695068_bcfa_credit_note', 'credit_note_number', 'CN0001');\r\n            if (allocation008.next()) {\r\n                this._insert('x_695068_bcfa_deduction', { payment_allocation: allocation008.getUniqueValue(), deduction_type: 'credit_note_netting', amount: 1000, credit_note: creditNote001, status: 'approved', notes: 'Netted against CN0001 — demo AR-008.' });\r\n            }\r\n            this.arService.exceptionEngine.resolveArException(ar008.detail.exceptionSysId, 'Residual netted against credit note CN0001.', requester);\r\n            this.arService.advanceAfterDeduction(ar008.paymentSysId);\r\n        }\r\n\r\n        // AR-009 Approval required: matched, left pending for a human.\r\n        var ar009 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-009', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C003'),\r\n            currency: 'EUR', amount: 22000, bankAccount: 'HU-COLL-009',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-009'\r\n        });\r\n        results['AR-009'] = ar009;\r\n        if (ar009.stoppedAt === 'PENDING_APPROVAL') {\r\n            this.arService.requestApproval(ar009.paymentSysId, requester);\r\n        }\r\n\r\n        // AR-010 Clearing timeout -> Unknown Outcome -> reconciled to CLEARED.\r\n        var ar010 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-010', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C009'),\r\n            currency: 'USD', amount: 5500, bankAccount: 'US-COLL-010',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-010'\r\n        });\r\n        results['AR-010'] = ar010;\r\n        if (ar010.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar010Approval = this.arService.requestApproval(ar010.paymentSysId, requester);\r\n            // Same cascade-timing fix as AP-009/AP-010: ArPaymentApprovalCascade\r\n            // auto-clears synchronously on approval using the active profile's\r\n            // failure mode, so the profile must be flipped before approving,\r\n            // not passed to a second clearPayment() call afterward.\r\n            this._setAdapterFailureMode('mock_sap', 'timeout');\r\n            this.arService.decideApproval(ar010.paymentSysId, ar010Approval.approvalSysId, 'approved', approver, 'Approved — will time out for demo AR-010.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ar010TxnSysId = this._latestIntegrationTxn('x_695068_bcfa_payment', ar010.paymentSysId, 'clearCustomerPayment');\r\n            results['AR-010'] = { intake: ar010, transactionSysId: ar010TxnSysId };\r\n            if (ar010TxnSysId) {\r\n                results['AR-010'].reconciliation = this.arService.reconcileClearing(ar010.paymentSysId, ar010TxnSysId);\r\n            }\r\n        }\r\n\r\n        return results;\r\n    },\r\n\r\n    // ---- Phase 13: POC 2 cash application scenarios -------------------------\r\n    // Three independent paths from the POC brief, each with its own\r\n    // fictional customer so they can be demoed in any order:\r\n    //   C1001  ARINV1001 50,000                  payment 50,000  (exact)\r\n    //   C1002  ARINV2001 50,000 + ARINV2002 30,000  payment 80,000  (multi-invoice)\r\n    //   C1003  ARINV3001 50,000 + ARINV3002 30,000  payment 79,500  (500 bank charge)\r\n    // The brief's example uses one customer (C1001) for all three; one\r\n    // customer each keeps the paths from consuming each other's open items.\r\n    // Payments arrive as bank statement lines (RECEIVED, customer unknown);\r\n    // the remittance PDFs in test/fixtures/AR_REMIT_10x drive the rest.\r\n    // Idempotent: existing records (by code / number / bank reference) are\r\n    // left untouched.\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedPoc2CashScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedPoc2CashScenarios(); });\r\n    },\r\n\r\n    _seedPoc2CashScenarios: function() {\r\n        var created = [];\r\n        var customers = [\r\n            { code: 'C1001', name: 'Sahyadri Tyre Works Pvt Ltd' },\r\n            { code: 'C1002', name: 'Nilgiri Rubber Compounds Ltd' },\r\n            { code: 'C1003', name: 'Vindhya Elastomers Pvt Ltd' }\r\n        ];\r\n        var customerSysId = {};\r\n        for (var c = 0; c < customers.length; c++) {\r\n            customerSysId[customers[c].code] = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', customers[c].code) ||\r\n                this._createdMark(created, customers[c].code, this._insert('x_695068_bcfa_customer', {\r\n                    customer_code: customers[c].code, name: customers[c].name, country: 'India', currency: 'INR', company_code: '1000', active: true\r\n                }));\r\n        }\r\n\r\n        var items = [\r\n            { item: 'ARINV1001', customer: 'C1001', amount: 50000, daysAgo: 30 },\r\n            { item: 'ARINV2001', customer: 'C1002', amount: 50000, daysAgo: 35 },\r\n            { item: 'ARINV2002', customer: 'C1002', amount: 30000, daysAgo: 20 },\r\n            { item: 'ARINV3001', customer: 'C1003', amount: 50000, daysAgo: 40 },\r\n            { item: 'ARINV3002', customer: 'C1003', amount: 30000, daysAgo: 25 }\r\n        ];\r\n        for (var i = 0; i < items.length; i++) {\r\n            if (this._lookupSysId('x_695068_bcfa_ar_open_item', 'item_number', items[i].item)) continue;\r\n            var due = new GlideDateTime();\r\n            due.addDaysUTC(-items[i].daysAgo);\r\n            this._createdMark(created, items[i].item, this._insert('x_695068_bcfa_ar_open_item', {\r\n                item_number: items[i].item, customer: customerSysId[items[i].customer], company_code: '1000', currency: 'INR',\r\n                invoice_amount: items[i].amount, open_amount: items[i].amount, due_date: due.getDate(), status: 'open'\r\n            }));\r\n        }\r\n\r\n        var payments = [\r\n            { ref: 'BANK-POC2-001', amount: 50000 },\r\n            { ref: 'BANK-POC2-002', amount: 80000 },\r\n            { ref: 'BANK-POC2-003', amount: 79500 }\r\n        ];\r\n        var paymentSysId = {};\r\n        for (var p = 0; p < payments.length; p++) {\r\n            paymentSysId[payments[p].ref] = this._lookupSysId('x_695068_bcfa_payment', 'bank_reference', payments[p].ref) ||\r\n                this._createdMark(created, payments[p].ref, this.arService.intakePayment({\r\n                    bankReference: payments[p].ref, currency: 'INR', amount: payments[p].amount, bankAccount: 'IN-COLL-POC2',\r\n                    valueDate: '2026-09-26', idempotencyKey: 'POC2-' + payments[p].ref\r\n                }).paymentSysId);\r\n        }\r\n        return { created: created, customers: customerSysId, payments: paymentSysId };\r\n    },\r\n\r\n    _createdMark: function(created, label, sysId) {\r\n        created.push(label);\r\n        return sysId;\r\n    },\r\n\r\n    // ---- Phase 6 (Claude AI layer) client demo scenarios --------------------\r\n    // Four purpose-built scenarios matching the client demo script exactly:\r\n    // AP happy path, AP amount-mismatch exception, Cash exact match, Cash\r\n    // short pay. Dedicated master data (own PO/receipt/AR-open-item) so\r\n    // these never interact with the original AP-001..010/AR-001..010 set.\r\n    // All four are deliberately left at their natural stopping point\r\n    // (PENDING_APPROVAL or EXCEPTION) rather than auto-approved — that's the\r\n    // live click-through moment for the actual client demo.\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedClaudeDemoScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedClaudeDemoScenarios(); });\r\n    },\r\n\r\n    _seedClaudeDemoScenarios: function() {\r\n        var alreadySeeded = new GlideRecord('x_695068_bcfa_purchase_order');\r\n        alreadySeeded.addQuery('po_number', 'PO-BC-1001');\r\n        alreadySeeded.query();\r\n        if (alreadySeeded.next()) return { skipped: true };\r\n\r\n        var results = {};\r\n        var vendor001 = this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001');\r\n        var vendor002 = this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V002');\r\n        var customer001 = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001');\r\n        var customer004 = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C004');\r\n\r\n        // --- AP-BC-1001: Happy path (India vendor, 18% GST, exact 3-way match) --\r\n        var po1001 = this._insert('x_695068_bcfa_purchase_order', {\r\n            po_number: 'PO-BC-1001', vendor: vendor001, company_code: '1000', currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n        });\r\n        var poLine1001 = this._insert('x_695068_bcfa_po_line', {\r\n            purchase_order: po1001, line_number: 1, material_or_service: 'Carbon black feedstock', quantity: 10, unit: 'MT', unit_price: 10000, received_quantity: 10\r\n        });\r\n        this._insert('x_695068_bcfa_receipt', {\r\n            receipt_number: 'RCPT-BC-1001', po_line: poLine1001, receipt_type: 'grn', quantity: 10, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO-BC-1001'\r\n        });\r\n\r\n        // seedExtraction deliberately includes invoice_date/posting_date —\r\n        // Claude's extraction prompt correctly flags genuinely missing dates\r\n        // as warnings and lowers confidence accordingly (proven by an\r\n        // earlier seed attempt that omitted them and legitimately tripped\r\n        // the low_confidence review path). A clean happy-path demo needs\r\n        // complete evidence, not a prompt workaround.\r\n        var todayStr1 = new GlideDateTime().getDate().getValue();\r\n        var apBc1001 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-BC-1001', vendor: vendor001, companyCode: '1000', currency: 'INR',\r\n            purchaseOrder: po1001, grossAmount: 118000, netAmount: 100000, taxAmount: 18000,\r\n            invoiceDate: new GlideDateTime().getDate(),\r\n            seedExtraction: { invoiceNumber: 'INV-BC-1001', vendor: 'V001', amount: 118000, invoice_date: todayStr1, posting_date: todayStr1 },\r\n            lines: [this._seedLine('PO-BC-1001', 'RCPT-BC-1001', 10, 10000, 18000, 100000)]\r\n        });\r\n        results['AP-BC-1001'] = { apInvoiceSysId: apBc1001.apInvoiceSysId, stoppedAt: apBc1001.stoppedAt };\r\n        if (apBc1001.stoppedAt === 'MATCHED') {\r\n            this.apService.requestApproval(apBc1001.apInvoiceSysId, this._twoUsers()[0]);\r\n        }\r\n\r\n        // --- AP-BC-1002: Amount-mismatch exception (invoice line price 3% ----\r\n        // above the PO line price — exceeds the 2% tolerance).\r\n        var po1002 = this._insert('x_695068_bcfa_purchase_order', {\r\n            po_number: 'PO-BC-1002', vendor: vendor002, company_code: '1000', currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n        });\r\n        var poLine1002 = this._insert('x_695068_bcfa_po_line', {\r\n            purchase_order: po1002, line_number: 1, material_or_service: 'Carbon black feedstock', quantity: 10, unit: 'MT', unit_price: 10000, received_quantity: 10\r\n        });\r\n        this._insert('x_695068_bcfa_receipt', {\r\n            receipt_number: 'RCPT-BC-1002', po_line: poLine1002, receipt_type: 'grn', quantity: 10, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO-BC-1002'\r\n        });\r\n\r\n        var todayStr2 = new GlideDateTime().getDate().getValue();\r\n        var apBc1002 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-BC-1002', vendor: vendor002, companyCode: '1000', currency: 'INR',\r\n            purchaseOrder: po1002, grossAmount: 121540, netAmount: 103000, taxAmount: 18540,\r\n            invoiceDate: new GlideDateTime().getDate(),\r\n            seedExtraction: { invoiceNumber: 'INV-BC-1002', vendor: 'V002', amount: 121540, invoice_date: todayStr2, posting_date: todayStr2 },\r\n            lines: [this._seedLine('PO-BC-1002', 'RCPT-BC-1002', 10, 10300, 18540, 103000)]\r\n        });\r\n        results['AP-BC-1002'] = { apInvoiceSysId: apBc1002.apInvoiceSysId, stoppedAt: apBc1002.stoppedAt };\r\n\r\n        // --- CASH-BC-0001: Exact match ------------------------------------------\r\n        var dueDate1 = new GlideDateTime();\r\n        dueDate1.addDaysUTC(30);\r\n        this._insert('x_695068_bcfa_ar_open_item', {\r\n            item_number: 'ARI-BC-0001', customer: customer001, company_code: '1000', currency: 'INR',\r\n            invoice_amount: 100000, open_amount: 100000, due_date: dueDate1.getDate(), status: 'open'\r\n        });\r\n        var cashBc0001 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-BC-0001', customer: customer001, currency: 'INR', amount: 100000, bankAccount: 'IN-COLL-BC-001',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-BC-0001'\r\n        });\r\n        results['CASH-BC-0001'] = cashBc0001;\r\n\r\n        // --- CASH-BC-0002: Short pay (paid 2500 less than the open item) -------\r\n        // Due date deliberately much older than any pre-existing open item\r\n        // for this customer (e.g. ARI0006) — multiInvoiceSuggestion greedily\r\n        // accumulates oldest-due-first until the running total reaches the\r\n        // payment amount, so this item must sort first or the demo's clean\r\n        // single-item short-pay picks up an extra unrelated item too.\r\n        var dueDate2 = new GlideDateTime();\r\n        dueDate2.addDaysUTC(-100);\r\n        this._insert('x_695068_bcfa_ar_open_item', {\r\n            item_number: 'ARI-BC-0002', customer: customer004, company_code: '1000', currency: 'EUR',\r\n            invoice_amount: 100000, open_amount: 100000, due_date: dueDate2.getDate(), status: 'open'\r\n        });\r\n        var cashBc0002 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'UTR20260917002', customer: customer004, currency: 'EUR', amount: 97500, bankAccount: 'DE-COLL-BC-002',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-BC-0002'\r\n        });\r\n        results['CASH-BC-0002'] = cashBc0002;\r\n\r\n        return results;\r\n    },\r\n\r\n    // ---- Demo reset (Phase 28) ---------------------------------------------\r\n\r\n    // Puts the application's data back to the seeded demo baseline:\r\n    //   deletes  every AP invoice and payment with their lines, extractions,\r\n    //            matches, exceptions, approvals, remittances, match\r\n    //            candidates, allocations and deductions; integration\r\n    //            transactions; document intakes (with attachments); finance\r\n    //            exceptions; KPI rows; and master rows outside the seeded\r\n    //            baseline (POs, PO lines, receipts, open items, credit notes\r\n    //            not in seedMasterData, e.g. test data)\r\n    //   keeps    vendors, customers, aliases, integration profiles,\r\n    //            reference mappings (configuration); the audit trail\r\n    //            (append-only) and the decision log; the AI Interaction Log\r\n    //            unless x_695068_bcfa.demo.reset_clears_ai_log = true\r\n    // then seedAll() restores the master data values and re-runs the 10 AP\r\n    // and 10 AR scenarios. The reset itself is audited.\r\n    //\r\n    // Refused unless confirm is exactly DemoDataSeeder.RESET_CONFIRMATION and\r\n    // x_695068_bcfa.demo.reset_enabled is true (set it to false on any\r\n    // instance whose data must never be reset).\r\n    resetAndReseed: function(confirm) {\r\n        var reset = this.resetDemoData(confirm);\r\n        if (reset.refused) return reset;\r\n        return { reset: reset, seed: this.seedAll() };\r\n    },\r\n\r\n    resetDemoData: function(confirm) {\r\n        if (confirm !== DemoDataSeeder.RESET_CONFIRMATION) return { refused: true, reason: 'Pass the confirmation text \"' + DemoDataSeeder.RESET_CONFIRMATION + '\".' };\r\n        if (gs.getProperty('x_695068_bcfa.demo.reset_enabled', 'false') !== 'true') return { refused: true, reason: 'x_695068_bcfa.demo.reset_enabled is not true on this instance.' };\r\n\r\n        var deleted = {};\r\n        var wipe = function(table, query) {\r\n            var gr = new GlideRecord(table);\r\n            if (query) gr.addEncodedQuery(query);\r\n            gr.query();\r\n            var n = gr.getRowCount();\r\n            if (n) {\r\n                gr.setWorkflow(false);\r\n                gr.deleteMultiple();\r\n            }\r\n            deleted[table.replace('x_695068_bcfa_', '')] = n;\r\n        };\r\n\r\n        // Document intakes: attachments first.\r\n        var intake = new GlideRecord('x_695068_bcfa_finance_intake');\r\n        intake.query();\r\n        var attachments = new GlideSysAttachment();\r\n        while (intake.next()) attachments.deleteAll(intake);\r\n\r\n        // Children before parents.\r\n        ['x_695068_bcfa_ap_match', 'x_695068_bcfa_ap_extraction', 'x_695068_bcfa_ap_invoice_line', 'x_695068_bcfa_ap_approval',\r\n            'x_695068_bcfa_ap_exception', 'x_695068_bcfa_ap_invoice',\r\n            'x_695068_bcfa_match_candidate', 'x_695068_bcfa_deduction', 'x_695068_bcfa_payment_allocation', 'x_695068_bcfa_remittance',\r\n            'x_695068_bcfa_ar_approval', 'x_695068_bcfa_ar_exception', 'x_695068_bcfa_payment',\r\n            'x_695068_bcfa_integration_txn', 'x_695068_bcfa_finance_intake', 'x_695068_bcfa_finance_exception', 'x_695068_bcfa_kpi'\r\n        ].forEach(function(t) { wipe(t); });\r\n        if (gs.getProperty('x_695068_bcfa.demo.reset_clears_ai_log', 'false') === 'true') wipe('x_695068_bcfa_ai_interaction');\r\n\r\n        // Master rows outside the seeded baseline (test data).\r\n        var codes = function(prefix, n, width) {\r\n            var list = [];\r\n            for (var i = 1; i <= n; i++) list.push(prefix + ('000' + i).slice(-width));\r\n            return list.join(',');\r\n        };\r\n        wipe('x_695068_bcfa_receipt', 'receipt_numberNOT IN' + codes('RCPT', 10, 4));\r\n        wipe('x_695068_bcfa_po_line', 'purchase_order.po_numberNOT IN' + codes('PO', 10, 4) + '^ORpurchase_orderISEMPTY');\r\n        wipe('x_695068_bcfa_purchase_order', 'po_numberNOT IN' + codes('PO', 10, 4));\r\n        wipe('x_695068_bcfa_ar_open_item', 'item_numberNOT IN' + codes('ARI', 15, 4));\r\n        wipe('x_695068_bcfa_credit_note', 'credit_note_numberNOT IN' + codes('CN', 5, 4));\r\n\r\n        new AuditEngine().logEvent({\r\n            sourceTable: 'x_695068_bcfa_ap_invoice',\r\n            process: 'platform',\r\n            eventType: 'closure',\r\n            actorType: 'user',\r\n            description: 'Demo data reset: operational data deleted, master data back to the seeded baseline (audit trail kept).',\r\n            afterValue: { reset: 'demo_data', deleted: deleted }\r\n        });\r\n        return { deleted: deleted };\r\n    },\r\n\r\n    type: 'DemoDataSeeder'\r\n};\r\n\r\nDemoDataSeeder.RESET_CONFIRMATION = 'RESET BCFA DEMO DATA';\r\n]]></script>\n    <sys_name>DemoDataSeeder</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_27d2fb84df4d47d487c59705a63fe43b.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>27d2fb84df4d47d487c59705a63fe43b</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_27d2fb84df4d47d487c59705a63fe43b</sys_update_name>\n    <content><![CDATA[// Stage 10/17 demo data. Deliberately scaled down from the brief's suggested\r\n// volumes (10 vendors/10 customers kept as-is; POs/receipts/open-items\r\n// reduced) because the 10 named AP/AR scenarios — the actual acceptance\r\n// criteria — need specific, deliberately-crafted supporting data more than\r\n// they need raw volume. See docs/BUILD_REPORT.md for this scope note.\r\n//\r\n// Run once via an ATF runServerSideScript step (see tests/) — there is no\r\n// other script-execution surface available to this build.\r\nvar DemoDataSeeder = Class.create();\r\nDemoDataSeeder.prototype = {\r\n    initialize: function() {\r\n        this.apService = new ApDomainService();\r\n        this.arService = new ArDomainService();\r\n    },\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedAll: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedAll(); });\r\n    },\r\n\r\n    _seedAll: function() {\r\n        // Phase 28: master data is upserted whenever the AP scenarios are\r\n        // absent (first seed, or after resetDemoData), so the scenarios start\r\n        // from the seeded baseline.\r\n        var scenariosPresent = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        scenariosPresent.addQuery('invoice_number', 'INV-AP-001');\r\n        scenariosPresent.query();\r\n        var masterData = scenariosPresent.hasNext() ? { skipped: true } : this.seedMasterData();\r\n\r\n        // AP/AR scenarios use fixed, deterministic keys (INV-AP-001,\r\n        // BANK-AR-001, ...) by design, so re-running this against an instance\r\n        // that already has them would trip the seeder's own duplicate/\r\n        // idempotency detection against its *own* prior output. Guard the\r\n        // same way seedMasterData() already does.\r\n        var apAlreadySeeded = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        apAlreadySeeded.addQuery('invoice_number', 'INV-AP-001');\r\n        apAlreadySeeded.query();\r\n        var apResults = apAlreadySeeded.next() ? { skipped: true } : this.seedApScenarios();\r\n\r\n        var arAlreadySeeded = new GlideRecord('x_695068_bcfa_payment');\r\n        arAlreadySeeded.addQuery('bank_reference', 'BANK-AR-001');\r\n        arAlreadySeeded.query();\r\n        var arResults = arAlreadySeeded.next() ? { skipped: true } : this.seedArScenarios();\r\n\r\n        return { masterData: masterData, apScenarios: apResults, arScenarios: arResults };\r\n    },\r\n\r\n    // [requester, approver]. Phase 17: approvals pass the segregation-of-\r\n    // duties gate (approver role, not the requester, not the processor, in\r\n    // the approval group), so the demo processor requests and the demo\r\n    // finance approver approves when those users exist.\r\n    _twoUsers: function() {\r\n        var processor = this._lookupSysId('sys_user', 'user_name', 'bcfa.ap.processor');\r\n        var approver = this._lookupSysId('sys_user', 'user_name', 'bcfa.finance.approver');\r\n        if (processor && approver) return [processor, approver];\r\n        var users = [];\r\n        var gr = new GlideRecord('sys_user');\r\n        gr.addQuery('active', true);\r\n        gr.orderBy('sys_created_on');\r\n        gr.setLimit(5);\r\n        gr.query();\r\n        while (gr.next() && users.length < 2) {\r\n            users.push(gr.getUniqueValue());\r\n        }\r\n        if (users.length === 0) users.push(gs.getUserID());\r\n        if (users.length === 1) users.push(users[0]);\r\n        return users;\r\n    },\r\n\r\n    // Updates the row matching all key fields, or inserts one. Returns sys_id.\r\n    _upsert: function(table, keys, fields) {\r\n        var gr = new GlideRecord(table);\r\n        for (var k in keys) gr.addQuery(k, keys[k]);\r\n        gr.setLimit(1);\r\n        gr.query();\r\n        if (!gr.next()) return this._insert(table, fields);\r\n        for (var key in fields) gr.setValue(key, fields[key]);\r\n        gr.update();\r\n        return gr.getUniqueValue();\r\n    },\r\n\r\n    _insert: function(table, fields) {\r\n        var gr = new GlideRecord(table);\r\n        gr.initialize();\r\n        for (var key in fields) {\r\n            gr.setValue(key, fields[key]);\r\n        }\r\n        return gr.insert();\r\n    },\r\n\r\n    // Phase 28: upserts by business key (vendor code, PO number, item number,\r\n    // ...). Existing rows keep their sys_id (reference mappings point at\r\n    // them) and get their seeded values back, e.g. an open item's open amount\r\n    // after a clearing consumed it.\r\n    seedMasterData: function() {\r\n        var vendorDefs = [\r\n            { vendor_code: 'V001', name: 'Rajasthan Carbon Feedstock Pvt Ltd', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0001' },\r\n            { vendor_code: 'V002', name: 'Gujarat Oil Traders Ltd', country: 'India', currency: 'INR', payment_terms: 'NET45', bank_account: 'IN-ACC-0002' },\r\n            { vendor_code: 'V003', name: 'Budapest Chemicals Kft', country: 'Hungary', currency: 'EUR', payment_terms: 'NET30', bank_account: 'HU-ACC-0003' },\r\n            { vendor_code: 'V004', name: 'Rhine Logistics GmbH', country: 'Germany', currency: 'EUR', payment_terms: 'NET30', bank_account: 'DE-ACC-0004' },\r\n            { vendor_code: 'V005', name: 'Gulf Coast Feedstock LLC', country: 'United States', currency: 'USD', payment_terms: 'NET60', bank_account: 'US-ACC-0005' },\r\n            { vendor_code: 'V006', name: 'Chennai Packaging Solutions', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0006' },\r\n            { vendor_code: 'V007', name: 'Miskolc Freight Services', country: 'Hungary', currency: 'EUR', payment_terms: 'NET15', bank_account: 'HU-ACC-0007' },\r\n            { vendor_code: 'V008', name: 'Bavaria Industrial Supplies AG', country: 'Germany', currency: 'EUR', payment_terms: 'NET30', bank_account: 'DE-ACC-0008' },\r\n            { vendor_code: 'V009', name: 'Texas Carbon Feedstock Inc', country: 'United States', currency: 'USD', payment_terms: 'NET45', bank_account: 'US-ACC-0009' },\r\n            { vendor_code: 'V010', name: 'Odisha Raw Materials Pvt Ltd', country: 'India', currency: 'INR', payment_terms: 'NET30', bank_account: 'IN-ACC-0010' }\r\n        ];\r\n        var vendorSysId = {};\r\n        for (var v = 0; v < vendorDefs.length; v++) {\r\n            var def = vendorDefs[v];\r\n            def.active = true;\r\n            vendorSysId[def.vendor_code] = this._upsert('x_695068_bcfa_vendor', { vendor_code: def.vendor_code }, def);\r\n        }\r\n\r\n        var customerDefs = [\r\n            { customer_code: 'C001', name: 'Continental Tyre Manufacturing', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C002', name: 'Deccan Rubber Industries', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C003', name: 'Pannonia Polymer Zrt', country: 'Hungary', currency: 'EUR' },\r\n            { customer_code: 'C004', name: 'Schwarzwald Elastomers GmbH', country: 'Germany', currency: 'EUR' },\r\n            { customer_code: 'C005', name: 'Lone Star Tyre Corp', country: 'United States', currency: 'USD' },\r\n            { customer_code: 'C006', name: 'Bengal Compounds Ltd', country: 'India', currency: 'INR' },\r\n            { customer_code: 'C007', name: 'Danube Rubber Kft', country: 'Hungary', currency: 'EUR' },\r\n            { customer_code: 'C008', name: 'Ruhr Valley Polymers AG', country: 'Germany', currency: 'EUR' },\r\n            { customer_code: 'C009', name: 'Pacific Coast Tyre Co', country: 'United States', currency: 'USD' },\r\n            { customer_code: 'C010', name: 'Karnataka Elastomers Pvt Ltd', country: 'India', currency: 'INR' }\r\n        ];\r\n        var customerSysId = {};\r\n        for (var c = 0; c < customerDefs.length; c++) {\r\n            var cdef = customerDefs[c];\r\n            cdef.active = true;\r\n            customerSysId[cdef.customer_code] = this._upsert('x_695068_bcfa_customer', { customer_code: cdef.customer_code }, cdef);\r\n        }\r\n        var customerCurrency = {};\r\n        for (var cc = 0; cc < customerDefs.length; cc++) customerCurrency[customerDefs[cc].customer_code] = customerDefs[cc].currency;\r\n\r\n        // Purchase orders + lines. Each entry describes one PO with one line.\r\n        var poDefs = [\r\n            { po: 'PO0001', vendorCode: 'V001', qty: 100, unitPrice: 50, unit: 'MT' },\r\n            { po: 'PO0002', vendorCode: 'V002', qty: 200, unitPrice: 30, unit: 'MT' },\r\n            { po: 'PO0003', vendorCode: 'V003', qty: 50, unitPrice: 120, unit: 'MT' },\r\n            { po: 'PO0004', vendorCode: 'V004', qty: 10, unitPrice: 500, unit: 'EA' },\r\n            { po: 'PO0005', vendorCode: 'V005', qty: 300, unitPrice: 40, unit: 'MT' },\r\n            { po: 'PO0006', vendorCode: 'V006', qty: 1000, unitPrice: 2, unit: 'EA' },\r\n            { po: 'PO0007', vendorCode: 'V007', qty: 20, unitPrice: 250, unit: 'EA' },\r\n            { po: 'PO0008', vendorCode: 'V008', qty: 75, unitPrice: 80, unit: 'MT' },\r\n            { po: 'PO0009', vendorCode: 'V009', qty: 150, unitPrice: 45, unit: 'MT' },\r\n            { po: 'PO0010', vendorCode: 'V010', qty: 90, unitPrice: 60, unit: 'MT' }\r\n        ];\r\n        var poLineSysId = {};\r\n        var poSysId = {};\r\n        for (var p = 0; p < poDefs.length; p++) {\r\n            var pdef = poDefs[p];\r\n            var poId = this._upsert('x_695068_bcfa_purchase_order', { po_number: pdef.po }, {\r\n                po_number: pdef.po, vendor: vendorSysId[pdef.vendorCode], company_code: '1000',\r\n                currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n            });\r\n            poSysId[pdef.po] = poId;\r\n            poLineSysId[pdef.po] = this._upsert('x_695068_bcfa_po_line', { purchase_order: poId, line_number: 1 }, {\r\n                purchase_order: poId, line_number: 1, material_or_service: 'Carbon black feedstock',\r\n                quantity: pdef.qty, unit: pdef.unit, unit_price: pdef.unitPrice, received_quantity: pdef.qty\r\n            });\r\n        }\r\n\r\n        // Receipts: most match their PO line exactly; RCPT0004 and RCPT0005\r\n        // are deliberately off to support AP-004/AP-005.\r\n        var receiptDefs = [\r\n            { receipt: 'RCPT0001', po: 'PO0001', qty: 100 },\r\n            { receipt: 'RCPT0002', po: 'PO0002', qty: 200 },\r\n            { receipt: 'RCPT0003', po: 'PO0003', qty: 50 },\r\n            { receipt: 'RCPT0004', po: 'PO0004', qty: 10 },\r\n            { receipt: 'RCPT0005', po: 'PO0005', qty: 300 },\r\n            { receipt: 'RCPT0006', po: 'PO0006', qty: 1000 },\r\n            { receipt: 'RCPT0007', po: 'PO0007', qty: 20 },\r\n            { receipt: 'RCPT0008', po: 'PO0008', qty: 75 },\r\n            { receipt: 'RCPT0009', po: 'PO0009', qty: 150 },\r\n            { receipt: 'RCPT0010', po: 'PO0010', qty: 90 }\r\n        ];\r\n        var receiptSysId = {};\r\n        for (var r = 0; r < receiptDefs.length; r++) {\r\n            var rdef = receiptDefs[r];\r\n            receiptSysId[rdef.receipt] = this._upsert('x_695068_bcfa_receipt', { receipt_number: rdef.receipt }, {\r\n                receipt_number: rdef.receipt, po_line: poLineSysId[rdef.po], receipt_type: 'grn',\r\n                quantity: rdef.qty, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO' + rdef.receipt\r\n            });\r\n        }\r\n\r\n        // AR open items spread across customers for exact/multi/partial match testing.\r\n        var itemDefs = [\r\n            { item: 'ARI0001', customerCode: 'C001', amount: 15000 },\r\n            { item: 'ARI0002', customerCode: 'C002', amount: 8000 },\r\n            { item: 'ARI0003', customerCode: 'C002', amount: 12000 },\r\n            { item: 'ARI0004', customerCode: 'C002', amount: 5000 },\r\n            { item: 'ARI0005', customerCode: 'C003', amount: 22000 },\r\n            { item: 'ARI0006', customerCode: 'C004', amount: 9500 },\r\n            { item: 'ARI0007', customerCode: 'C005', amount: 30000 },\r\n            { item: 'ARI0008', customerCode: 'C006', amount: 4200 },\r\n            { item: 'ARI0009', customerCode: 'C007', amount: 17500 },\r\n            { item: 'ARI0010', customerCode: 'C008', amount: 6800 },\r\n            { item: 'ARI0011', customerCode: 'C009', amount: 25000 },\r\n            { item: 'ARI0012', customerCode: 'C010', amount: 11000 },\r\n            { item: 'ARI0013', customerCode: 'C001', amount: 3000 },\r\n            { item: 'ARI0014', customerCode: 'C003', amount: 7000 },\r\n            { item: 'ARI0015', customerCode: 'C009', amount: 5500 }\r\n        ];\r\n        var itemSysId = {};\r\n        for (var i = 0; i < itemDefs.length; i++) {\r\n            var idef = itemDefs[i];\r\n            // Stagger due dates by index rather than stamping every item with\r\n            // today's date — multiInvoiceSuggestion orders by due_date\r\n            // (\"oldest first\"), and identical dates made that ordering\r\n            // meaningless (effectively arbitrary/insertion-order), which is\r\n            // what let AR-008's fuzzy match silently grab C001's much larger\r\n            // ARI0001 instead of the small ARI0013 the credit-note-netting\r\n            // demo actually needs.\r\n            var dueDate = new GlideDateTime();\r\n            dueDate.addDaysUTC(-i);\r\n            itemSysId[idef.item] = this._upsert('x_695068_bcfa_ar_open_item', { item_number: idef.item }, {\r\n                item_number: idef.item, customer: customerSysId[idef.customerCode], company_code: '1000',\r\n                // Phase 14: the item currency follows the customer (was always\r\n                // INR, which let EUR/USD payments match INR items).\r\n                currency: customerCurrency[idef.customerCode], invoice_amount: idef.amount, open_amount: idef.amount,\r\n                due_date: dueDate.getDate(), status: 'open'\r\n            });\r\n        }\r\n\r\n        var creditNoteDefs = [\r\n            { cn: 'CN0001', customerCode: 'C001', amount: 1000 },\r\n            { cn: 'CN0002', customerCode: 'C002', amount: 500 },\r\n            { cn: 'CN0003', customerCode: 'C005', amount: 2000 },\r\n            { cn: 'CN0004', customerCode: 'C007', amount: 750 },\r\n            { cn: 'CN0005', customerCode: 'C009', amount: 1200 }\r\n        ];\r\n        for (var n = 0; n < creditNoteDefs.length; n++) {\r\n            var ndef = creditNoteDefs[n];\r\n            this._upsert('x_695068_bcfa_credit_note', { credit_note_number: ndef.cn }, {\r\n                credit_note_number: ndef.cn, customer: customerSysId[ndef.customerCode],\r\n                amount: ndef.amount, open_amount: ndef.amount, issue_date: new GlideDateTime().getDate(), status: 'open'\r\n            });\r\n        }\r\n\r\n        // Customer alias for AR-004.\r\n        this._upsert('x_695068_bcfa_customer_alias', { alias_name: 'LONE STAR TYRE CO' }, {\r\n            customer: customerSysId['C005'], alias_name: 'LONE STAR TYRE CO', alias_type: 'bank_remitter_name', confidence: 0.9, active: true\r\n        });\r\n\r\n        // Integration Profiles (Section 9) — all default to success; Stage 12\r\n        // resilience tests flip these temporarily.\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock SAP - Default' }, { name: 'Mock SAP - Default', adapter: 'mock_sap', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock Bank - Default' }, { name: 'Mock Bank - Default', adapter: 'mock_bank', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n        this._upsert('x_695068_bcfa_integration_profile', { name: 'Mock Archive - Default' }, { name: 'Mock Archive - Default', adapter: 'mock_archive', mode: 'simulation', active: true, response_delay_ms: 0, failure_mode: 'success' });\r\n\r\n        this._vendorSysId = vendorSysId;\r\n        this._customerSysId = customerSysId;\r\n        this._poSysId = poSysId;\r\n        this._poLineSysId = poLineSysId;\r\n        this._receiptSysId = receiptSysId;\r\n        this._itemSysId = itemSysId;\r\n\r\n        return {\r\n            vendors: vendorDefs.length, customers: customerDefs.length, purchaseOrders: poDefs.length,\r\n            receipts: receiptDefs.length, arOpenItems: itemDefs.length, creditNotes: creditNoteDefs.length\r\n        };\r\n    },\r\n\r\n    _lookupSysId: function(table, field, value) {\r\n        var gr = new GlideRecord(table);\r\n        if (gr.get(field, value)) return gr.getUniqueValue();\r\n        return null;\r\n    },\r\n\r\n    // The approval cascade Business Rules (ApInvoiceApprovalCascade /\r\n    // ArPaymentApprovalCascade) always auto-post/auto-clear synchronously on\r\n    // approval using the *active* Integration Profile's failure_mode — they\r\n    // never see a per-call simulateOutcome. To demo a specific SAP outcome\r\n    // (AP-009/AP-010/AR-010) the profile itself must be flipped immediately\r\n    // before the approval call and restored immediately after, rather than\r\n    // making a second explicit postInvoice()/clearPayment() call afterward —\r\n    // that second call would just replay the cascade's own already-successful\r\n    // result via the idempotency cache and never actually simulate anything.\r\n    _setAdapterFailureMode: function(adapter, mode) {\r\n        var gr = new GlideRecord('x_695068_bcfa_integration_profile');\r\n        gr.addQuery('adapter', adapter);\r\n        gr.addQuery('active', true);\r\n        gr.query();\r\n        while (gr.next()) {\r\n            gr.setValue('failure_mode', mode);\r\n            gr.update();\r\n        }\r\n    },\r\n\r\n    _latestIntegrationTxn: function(sourceTable, sourceRecord, operation) {\r\n        var gr = new GlideRecord('x_695068_bcfa_integration_txn');\r\n        gr.addQuery('source_table', sourceTable);\r\n        gr.addQuery('source_record', sourceRecord);\r\n        gr.addQuery('operation', operation);\r\n        gr.orderByDesc('sys_created_on');\r\n        gr.setLimit(1);\r\n        gr.query();\r\n        return gr.next() ? gr.getUniqueValue() : null;\r\n    },\r\n\r\n    // ---- AP scenarios (Section 17/19) ---------------------------------------\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedApScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedApScenarios(); });\r\n    },\r\n\r\n    _seedApScenarios: function() {\r\n        var users = this._twoUsers();\r\n        var requester = users[0];\r\n        var approver = users[1];\r\n        var results = {};\r\n\r\n        // AP-001 Happy path: full lifecycle through CLOSED.\r\n        var ap001 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-001', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0001'),\r\n            grossAmount: 5000, taxAmount: 900, netAmount: 5000,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-001', vendor: 'V001', amount: 5000 },\r\n            lines: [this._seedLine('PO0001', 'RCPT0001', 100, 50, 900, 5000)]\r\n        });\r\n        results['AP-001'] = ap001;\r\n        if (ap001.stoppedAt === 'MATCHED') {\r\n            var ap001Approval = this.apService.requestApproval(ap001.apInvoiceSysId, requester);\r\n            this.apService.decideApproval(ap001.apInvoiceSysId, ap001Approval.approvalSysId, 'approved', approver, 'Approved for demo AP-001 happy path.');\r\n        }\r\n\r\n        // AP-002 Duplicate invoice: same vendor/invoice_number/amount as AP-001.\r\n        var ap002 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-001', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001'),\r\n            companyCode: '1000', currency: 'INR', grossAmount: 5000, netAmount: 5000, taxAmount: 900,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-001', vendor: 'V001', amount: 5000 }\r\n        });\r\n        results['AP-002'] = ap002;\r\n\r\n        // AP-003 PO mismatch: purchase_order left unset intentionally, but the\r\n        // invoice text implies one was expected — validateInvoice does not\r\n        // fail on a missing PO by itself, so we simulate the mismatch by\r\n        // pointing at a PO line that does not belong to any PO record.\r\n        var ap003 = this.apService.intakeInvoice({\r\n            invoiceNumber: 'INV-AP-003', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V002'),\r\n            companyCode: '1000', currency: 'INR', grossAmount: 6000, netAmount: 6000, taxAmount: 1080\r\n        });\r\n        this.apService.runExtraction(ap003.apInvoiceSysId, { invoiceNumber: 'INV-AP-003' });\r\n        var invoice003 = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n        invoice003.get(ap003.apInvoiceSysId);\r\n        invoice003.setValue('purchase_order', gs.generateGUID());\r\n        invoice003.update();\r\n        results['AP-003'] = this.apService.validateInvoice(ap003.apInvoiceSysId);\r\n\r\n        // AP-004 Quantity tolerance failure: line quantity far exceeds receipt.\r\n        var ap004 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-004', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V004'),\r\n            companyCode: '1000', currency: 'EUR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0004'),\r\n            grossAmount: 5000, netAmount: 5000, taxAmount: 950,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-004' },\r\n            lines: [this._seedLine('PO0004', 'RCPT0004', 15, 500, 950, 5000)]\r\n        });\r\n        results['AP-004'] = ap004;\r\n\r\n        // AP-005 Price tolerance failure: unit price far above PO price.\r\n        var ap005 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-005', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V005'),\r\n            companyCode: '1000', currency: 'USD', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0005'),\r\n            grossAmount: 15000, netAmount: 15000, taxAmount: 0,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-005' },\r\n            lines: [this._seedLine('PO0005', 'RCPT0005', 300, 50, 0, 15000)]\r\n        });\r\n        results['AP-005'] = ap005;\r\n\r\n        // AP-006 Tax validation failure: India vendor, tax far off 18%.\r\n        var ap006 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-006', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V006'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0006'),\r\n            grossAmount: 2100, netAmount: 2000, taxAmount: 50,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-006' },\r\n            lines: [this._seedLine('PO0006', 'RCPT0006', 1000, 2, 50, 2000)]\r\n        });\r\n        results['AP-006'] = ap006;\r\n\r\n        // AP-007 Low-confidence extraction.\r\n        var ap007 = this.apService.intakeInvoice({\r\n            invoiceNumber: 'INV-AP-007', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V007'),\r\n            companyCode: '1000', currency: 'EUR', grossAmount: 3000, netAmount: 3000, taxAmount: 0\r\n        });\r\n        this.apService.runExtraction(ap007.apInvoiceSysId, { invoiceNumber: 'INV-AP-007' }, { forceConfidence: 0.5 });\r\n        results['AP-007'] = this.apService.validateInvoice(ap007.apInvoiceSysId);\r\n\r\n        // AP-008 Approval required: matched, left pending for a human.\r\n        var ap008 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-008', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V008'),\r\n            companyCode: '1000', currency: 'EUR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0008'),\r\n            grossAmount: 6000, netAmount: 6000, taxAmount: 1140,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-008' },\r\n            lines: [this._seedLine('PO0008', 'RCPT0008', 75, 80, 1140, 6000)]\r\n        });\r\n        if (ap008.stoppedAt === 'MATCHED') this.apService.requestApproval(ap008.apInvoiceSysId, requester);\r\n        results['AP-008'] = ap008;\r\n\r\n        // AP-009 SAP posting failure.\r\n        var ap009 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-009', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V009'),\r\n            companyCode: '1000', currency: 'USD', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0009'),\r\n            grossAmount: 6750, netAmount: 6750, taxAmount: 0,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-009' },\r\n            lines: [this._seedLine('PO0009', 'RCPT0009', 150, 45, 0, 6750)]\r\n        });\r\n        if (ap009.stoppedAt === 'MATCHED') {\r\n            var ap009Approval = this.apService.requestApproval(ap009.apInvoiceSysId, requester);\r\n            this._setAdapterFailureMode('mock_sap', 'technical_error');\r\n            this.apService.decideApproval(ap009.apInvoiceSysId, ap009Approval.approvalSysId, 'approved', approver, 'Approved — will fail at SAP for demo AP-009.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ap009Invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\r\n            ap009Invoice.get(ap009.apInvoiceSysId);\r\n            results['AP-009'] = {\r\n                posted: false,\r\n                failed: ap009Invoice.getValue('posting_state') === 'failed',\r\n                postingState: ap009Invoice.getValue('posting_state'),\r\n                state: ap009Invoice.getValue('state')\r\n            };\r\n        } else {\r\n            results['AP-009'] = { error: 'match failed unexpectedly', detail: ap009 };\r\n        }\r\n\r\n        // AP-010 SAP timeout -> Unknown Outcome -> reconciled to POSTED (Demo 3).\r\n        // taxAmount is 18% of netAmount (India vendor rate, see\r\n        // docs/BUSINESS_RULES.md's country tax table) — an earlier version of\r\n        // this scenario hardcoded taxAmount: 0, which itself failed tax\r\n        // validation before ever reaching the posting step this scenario is\r\n        // meant to demonstrate.\r\n        var ap010 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-AP-010', vendor: this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V010'),\r\n            companyCode: '1000', currency: 'INR', purchaseOrder: this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', 'PO0010'),\r\n            grossAmount: 6372, netAmount: 5400, taxAmount: 972,\r\n            seedExtraction: { invoiceNumber: 'INV-AP-010' },\r\n            lines: [this._seedLine('PO0010', 'RCPT0010', 90, 60, 972, 5400)]\r\n        });\r\n        if (ap010.stoppedAt === 'MATCHED') {\r\n            var ap010Approval = this.apService.requestApproval(ap010.apInvoiceSysId, requester);\r\n            this._setAdapterFailureMode('mock_sap', 'timeout');\r\n            this.apService.decideApproval(ap010.apInvoiceSysId, ap010Approval.approvalSysId, 'approved', approver, 'Approved — will time out for demo AP-010.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ap010TxnSysId = this._latestIntegrationTxn('x_695068_bcfa_ap_invoice', ap010.apInvoiceSysId, 'postVendorInvoice');\r\n            results['AP-010'] = { transactionSysId: ap010TxnSysId };\r\n            if (ap010TxnSysId) {\r\n                results['AP-010'].reconciliation = this.apService.reconcilePosting(ap010.apInvoiceSysId, ap010TxnSysId);\r\n            }\r\n        } else {\r\n            results['AP-010'] = { error: 'match failed unexpectedly', detail: ap010 };\r\n        }\r\n\r\n        return results;\r\n    },\r\n\r\n    // Invoice line in ApDomainService.attachInvoiceLine field shape, linked\r\n    // to the PO's (single) line and the given receipt. Phase 14: lines are\r\n    // attached at intake so the 3-way match sees them (a PO invoice without\r\n    // linked, received lines now fails matching).\r\n    _seedLine: function(poNumber, receiptNumber, quantity, unitPrice, tax, amount) {\r\n        return {\r\n            lineNumber: 1, materialOrService: 'Carbon black feedstock', quantity: quantity, unit: 'MT', unitPrice: unitPrice, tax: tax, amount: amount,\r\n            poLine: this._lookupSysId('x_695068_bcfa_po_line', 'purchase_order', this._lookupSysId('x_695068_bcfa_purchase_order', 'po_number', poNumber)),\r\n            receiptReference: this._lookupSysId('x_695068_bcfa_receipt', 'receipt_number', receiptNumber)\r\n        };\r\n    },\r\n\r\n    // ---- AR scenarios (Section 17/19) ---------------------------------------\r\n\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedArScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedArScenarios(); });\r\n    },\r\n\r\n    _seedArScenarios: function() {\r\n        var users = this._twoUsers();\r\n        var requester = users[0];\r\n        var approver = users[1];\r\n        var results = {};\r\n\r\n        // AR-001 Exact match: payment equals ARI0001's open amount exactly.\r\n        var ar001 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-001', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001'),\r\n            currency: 'INR', amount: 15000, bankAccount: 'IN-COLL-001',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-001'\r\n        });\r\n        results['AR-001'] = ar001;\r\n        if (ar001.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar001Approval = this.arService.requestApproval(ar001.paymentSysId, requester);\r\n            this.arService.decideApproval(ar001.paymentSysId, ar001Approval.approvalSysId, 'approved', approver, 'Approved for demo AR-001.');\r\n        }\r\n\r\n        // AR-002 Partial payment: less than ARI0006's open amount, only\r\n        // candidate available for that customer.\r\n        var ar002 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-002', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C004'),\r\n            currency: 'EUR', amount: 6000, bankAccount: 'DE-COLL-002',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-002'\r\n        });\r\n        results['AR-002'] = ar002;\r\n\r\n        // AR-003 Multi-invoice allocation: sum of ARI0002+ARI0003+ARI0004 = 25000.\r\n        var ar003 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-003', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C002'),\r\n            currency: 'INR', amount: 25000, bankAccount: 'IN-COLL-003',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-003'\r\n        });\r\n        results['AR-003'] = ar003;\r\n        if (ar003.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar003Approval = this.arService.requestApproval(ar003.paymentSysId, requester);\r\n            this.arService.decideApproval(ar003.paymentSysId, ar003Approval.approvalSysId, 'approved', approver, 'Approved for demo AR-003.');\r\n        }\r\n\r\n        // AR-004 Customer alias: customer left unset, resolved via alias.\r\n        var ar004 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-004', currency: 'USD', amount: 30000, bankAccount: 'US-COLL-004',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-004', candidateCustomerName: 'LONE STAR TYRE CO'\r\n        });\r\n        results['AR-004'] = ar004;\r\n\r\n        // AR-005 Unmatched payment: customer with no open items (C010 already\r\n        // has ARI0012, so pick an amount nothing sums to and no candidate\r\n        // customer at all).\r\n        var ar005 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-005', currency: 'INR', amount: 99999, bankAccount: 'IN-COLL-005',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-005', candidateCustomerName: 'UNKNOWN REMITTER XYZ'\r\n        });\r\n        results['AR-005'] = ar005;\r\n\r\n        // AR-006 Short pay: less than ARI0009's open amount.\r\n        var ar006 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-006', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C007'),\r\n            currency: 'EUR', amount: 15000, bankAccount: 'HU-COLL-006',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-006'\r\n        });\r\n        results['AR-006'] = ar006;\r\n        if (ar006.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            this.arService.exceptionEngine.resolveArException(ar006.detail.exceptionSysId, 'Confirmed with customer: intentional short-pay pending credit memo. Approved to proceed as-is for demo.', requester);\r\n            this.arService.forceProceedDespiteImbalance(ar006.paymentSysId, 'Manager override: proceeding despite confirmed short-pay — demo AR-006.');\r\n        }\r\n\r\n        // AR-007 Bank charge: payment is open_amount minus a small bank\r\n        // charge — flagged as short_pay, then a reviewer records the\r\n        // deduction (see docs/BUSINESS_RULES.md limitation note on\r\n        // auto-classifying deductions).\r\n        var ar007 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-007', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C010'),\r\n            currency: 'INR', amount: 10975, bankAccount: 'IN-COLL-007',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-007'\r\n        });\r\n        results['AR-007'] = ar007;\r\n        if (ar007.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            var allocation007 = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n            allocation007.addQuery('payment', ar007.paymentSysId);\r\n            allocation007.query();\r\n            if (allocation007.next()) {\r\n                this._insert('x_695068_bcfa_deduction', { payment_allocation: allocation007.getUniqueValue(), deduction_type: 'bank_charge', amount: 25, status: 'approved', notes: 'Bank charge identified during review — demo AR-007.' });\r\n            }\r\n            this.arService.exceptionEngine.resolveArException(ar007.detail.exceptionSysId, 'Bank charge of 25 identified and recorded as a deduction.', requester);\r\n            this.arService.advanceAfterDeduction(ar007.paymentSysId);\r\n        }\r\n\r\n        // AR-008 Credit note netting: payment short by the amount of CN0001.\r\n        var ar008 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-008', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001'),\r\n            currency: 'INR', amount: 2000, bankAccount: 'IN-COLL-008',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-008'\r\n        });\r\n        results['AR-008'] = ar008;\r\n        if (ar008.stoppedAt === 'ALLOCATION_EXCEPTION') {\r\n            var allocation008 = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n            allocation008.addQuery('payment', ar008.paymentSysId);\r\n            allocation008.query();\r\n            var creditNote001 = this._lookupSysId('x_695068_bcfa_credit_note', 'credit_note_number', 'CN0001');\r\n            if (allocation008.next()) {\r\n                this._insert('x_695068_bcfa_deduction', { payment_allocation: allocation008.getUniqueValue(), deduction_type: 'credit_note_netting', amount: 1000, credit_note: creditNote001, status: 'approved', notes: 'Netted against CN0001 — demo AR-008.' });\r\n            }\r\n            this.arService.exceptionEngine.resolveArException(ar008.detail.exceptionSysId, 'Residual netted against credit note CN0001.', requester);\r\n            this.arService.advanceAfterDeduction(ar008.paymentSysId);\r\n        }\r\n\r\n        // AR-009 Approval required: matched, left pending for a human.\r\n        var ar009 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-009', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C003'),\r\n            currency: 'EUR', amount: 22000, bankAccount: 'HU-COLL-009',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-009'\r\n        });\r\n        results['AR-009'] = ar009;\r\n        if (ar009.stoppedAt === 'PENDING_APPROVAL') {\r\n            this.arService.requestApproval(ar009.paymentSysId, requester);\r\n        }\r\n\r\n        // AR-010 Clearing timeout -> Unknown Outcome -> reconciled to CLEARED.\r\n        var ar010 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-AR-010', customer: this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C009'),\r\n            currency: 'USD', amount: 5500, bankAccount: 'US-COLL-010',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-010'\r\n        });\r\n        results['AR-010'] = ar010;\r\n        if (ar010.stoppedAt === 'PENDING_APPROVAL') {\r\n            var ar010Approval = this.arService.requestApproval(ar010.paymentSysId, requester);\r\n            // Same cascade-timing fix as AP-009/AP-010: ArPaymentApprovalCascade\r\n            // auto-clears synchronously on approval using the active profile's\r\n            // failure mode, so the profile must be flipped before approving,\r\n            // not passed to a second clearPayment() call afterward.\r\n            this._setAdapterFailureMode('mock_sap', 'timeout');\r\n            this.arService.decideApproval(ar010.paymentSysId, ar010Approval.approvalSysId, 'approved', approver, 'Approved — will time out for demo AR-010.');\r\n            this._setAdapterFailureMode('mock_sap', 'success');\r\n            var ar010TxnSysId = this._latestIntegrationTxn('x_695068_bcfa_payment', ar010.paymentSysId, 'clearCustomerPayment');\r\n            results['AR-010'] = { intake: ar010, transactionSysId: ar010TxnSysId };\r\n            if (ar010TxnSysId) {\r\n                results['AR-010'].reconciliation = this.arService.reconcileClearing(ar010.paymentSysId, ar010TxnSysId);\r\n            }\r\n        }\r\n\r\n        return results;\r\n    },\r\n\r\n    // ---- Phase 13: POC 2 cash application scenarios -------------------------\r\n    // Three independent paths from the POC brief, each with its own\r\n    // fictional customer so they can be demoed in any order:\r\n    //   C1001  ARINV1001 50,000                  payment 50,000  (exact)\r\n    //   C1002  ARINV2001 50,000 + ARINV2002 30,000  payment 80,000  (multi-invoice)\r\n    //   C1003  ARINV3001 50,000 + ARINV3002 30,000  payment 79,500  (500 bank charge)\r\n    // The brief's example uses one customer (C1001) for all three; one\r\n    // customer each keeps the paths from consuming each other's open items.\r\n    // Payments arrive as bank statement lines (RECEIVED, customer unknown);\r\n    // the remittance PDFs in test/fixtures/AR_REMIT_10x drive the rest.\r\n    // Idempotent: existing records (by code / number / bank reference) are\r\n    // left untouched.\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedPoc2CashScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedPoc2CashScenarios(); });\r\n    },\r\n\r\n    _seedPoc2CashScenarios: function() {\r\n        var created = [];\r\n        var customers = [\r\n            { code: 'C1001', name: 'Sahyadri Tyre Works Pvt Ltd' },\r\n            { code: 'C1002', name: 'Nilgiri Rubber Compounds Ltd' },\r\n            { code: 'C1003', name: 'Vindhya Elastomers Pvt Ltd' }\r\n        ];\r\n        var customerSysId = {};\r\n        for (var c = 0; c < customers.length; c++) {\r\n            customerSysId[customers[c].code] = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', customers[c].code) ||\r\n                this._createdMark(created, customers[c].code, this._insert('x_695068_bcfa_customer', {\r\n                    customer_code: customers[c].code, name: customers[c].name, country: 'India', currency: 'INR', company_code: '1000', active: true\r\n                }));\r\n        }\r\n\r\n        var items = [\r\n            { item: 'ARINV1001', customer: 'C1001', amount: 50000, daysAgo: 30 },\r\n            { item: 'ARINV2001', customer: 'C1002', amount: 50000, daysAgo: 35 },\r\n            { item: 'ARINV2002', customer: 'C1002', amount: 30000, daysAgo: 20 },\r\n            { item: 'ARINV3001', customer: 'C1003', amount: 50000, daysAgo: 40 },\r\n            { item: 'ARINV3002', customer: 'C1003', amount: 30000, daysAgo: 25 }\r\n        ];\r\n        for (var i = 0; i < items.length; i++) {\r\n            if (this._lookupSysId('x_695068_bcfa_ar_open_item', 'item_number', items[i].item)) continue;\r\n            var due = new GlideDateTime();\r\n            due.addDaysUTC(-items[i].daysAgo);\r\n            this._createdMark(created, items[i].item, this._insert('x_695068_bcfa_ar_open_item', {\r\n                item_number: items[i].item, customer: customerSysId[items[i].customer], company_code: '1000', currency: 'INR',\r\n                invoice_amount: items[i].amount, open_amount: items[i].amount, due_date: due.getDate(), status: 'open'\r\n            }));\r\n        }\r\n\r\n        var payments = [\r\n            { ref: 'BANK-POC2-001', amount: 50000 },\r\n            { ref: 'BANK-POC2-002', amount: 80000 },\r\n            { ref: 'BANK-POC2-003', amount: 79500 }\r\n        ];\r\n        var paymentSysId = {};\r\n        for (var p = 0; p < payments.length; p++) {\r\n            paymentSysId[payments[p].ref] = this._lookupSysId('x_695068_bcfa_payment', 'bank_reference', payments[p].ref) ||\r\n                this._createdMark(created, payments[p].ref, this.arService.intakePayment({\r\n                    bankReference: payments[p].ref, currency: 'INR', amount: payments[p].amount, bankAccount: 'IN-COLL-POC2',\r\n                    valueDate: '2026-09-26', idempotencyKey: 'POC2-' + payments[p].ref\r\n                }).paymentSysId);\r\n        }\r\n        return { created: created, customers: customerSysId, payments: paymentSysId };\r\n    },\r\n\r\n    _createdMark: function(created, label, sysId) {\r\n        created.push(label);\r\n        return sysId;\r\n    },\r\n\r\n    // ---- Phase 6 (Claude AI layer) client demo scenarios --------------------\r\n    // Four purpose-built scenarios matching the client demo script exactly:\r\n    // AP happy path, AP amount-mismatch exception, Cash exact match, Cash\r\n    // short pay. Dedicated master data (own PO/receipt/AR-open-item) so\r\n    // these never interact with the original AP-001..010/AR-001..010 set.\r\n    // All four are deliberately left at their natural stopping point\r\n    // (PENDING_APPROVAL or EXCEPTION) rather than auto-approved — that's the\r\n    // live click-through moment for the actual client demo.\r\n    // Phase 25: demo seeding runs the pipeline synchronously (inline).\r\n    seedClaudeDemoScenarios: function() {\r\n        var self = this;\r\n        return FinanceOrchestration.runInline(function() { return self._seedClaudeDemoScenarios(); });\r\n    },\r\n\r\n    _seedClaudeDemoScenarios: function() {\r\n        var alreadySeeded = new GlideRecord('x_695068_bcfa_purchase_order');\r\n        alreadySeeded.addQuery('po_number', 'PO-BC-1001');\r\n        alreadySeeded.query();\r\n        if (alreadySeeded.next()) return { skipped: true };\r\n\r\n        var results = {};\r\n        var vendor001 = this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V001');\r\n        var vendor002 = this._lookupSysId('x_695068_bcfa_vendor', 'vendor_code', 'V002');\r\n        var customer001 = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C001');\r\n        var customer004 = this._lookupSysId('x_695068_bcfa_customer', 'customer_code', 'C004');\r\n\r\n        // --- AP-BC-1001: Happy path (India vendor, 18% GST, exact 3-way match) --\r\n        var po1001 = this._insert('x_695068_bcfa_purchase_order', {\r\n            po_number: 'PO-BC-1001', vendor: vendor001, company_code: '1000', currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n        });\r\n        var poLine1001 = this._insert('x_695068_bcfa_po_line', {\r\n            purchase_order: po1001, line_number: 1, material_or_service: 'Carbon black feedstock', quantity: 10, unit: 'MT', unit_price: 10000, received_quantity: 10\r\n        });\r\n        this._insert('x_695068_bcfa_receipt', {\r\n            receipt_number: 'RCPT-BC-1001', po_line: poLine1001, receipt_type: 'grn', quantity: 10, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO-BC-1001'\r\n        });\r\n\r\n        // seedExtraction deliberately includes invoice_date/posting_date —\r\n        // Claude's extraction prompt correctly flags genuinely missing dates\r\n        // as warnings and lowers confidence accordingly (proven by an\r\n        // earlier seed attempt that omitted them and legitimately tripped\r\n        // the low_confidence review path). A clean happy-path demo needs\r\n        // complete evidence, not a prompt workaround.\r\n        var todayStr1 = new GlideDateTime().getDate().getValue();\r\n        var apBc1001 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-BC-1001', vendor: vendor001, companyCode: '1000', currency: 'INR',\r\n            purchaseOrder: po1001, grossAmount: 118000, netAmount: 100000, taxAmount: 18000,\r\n            invoiceDate: new GlideDateTime().getDate(),\r\n            seedExtraction: { invoiceNumber: 'INV-BC-1001', vendor: 'V001', amount: 118000, invoice_date: todayStr1, posting_date: todayStr1 },\r\n            lines: [this._seedLine('PO-BC-1001', 'RCPT-BC-1001', 10, 10000, 18000, 100000)]\r\n        });\r\n        results['AP-BC-1001'] = { apInvoiceSysId: apBc1001.apInvoiceSysId, stoppedAt: apBc1001.stoppedAt };\r\n        if (apBc1001.stoppedAt === 'MATCHED') {\r\n            this.apService.requestApproval(apBc1001.apInvoiceSysId, this._twoUsers()[0]);\r\n        }\r\n\r\n        // --- AP-BC-1002: Amount-mismatch exception (invoice line price 3% ----\r\n        // above the PO line price — exceeds the 2% tolerance).\r\n        var po1002 = this._insert('x_695068_bcfa_purchase_order', {\r\n            po_number: 'PO-BC-1002', vendor: vendor002, company_code: '1000', currency: 'INR', status: 'open', created_date: new GlideDateTime().getDate()\r\n        });\r\n        var poLine1002 = this._insert('x_695068_bcfa_po_line', {\r\n            purchase_order: po1002, line_number: 1, material_or_service: 'Carbon black feedstock', quantity: 10, unit: 'MT', unit_price: 10000, received_quantity: 10\r\n        });\r\n        this._insert('x_695068_bcfa_receipt', {\r\n            receipt_number: 'RCPT-BC-1002', po_line: poLine1002, receipt_type: 'grn', quantity: 10, receipt_date: new GlideDateTime().getDate(), sap_document_id: 'MIGO-BC-1002'\r\n        });\r\n\r\n        var todayStr2 = new GlideDateTime().getDate().getValue();\r\n        var apBc1002 = this.apService.intakeAndAutoProcess({\r\n            invoiceNumber: 'INV-BC-1002', vendor: vendor002, companyCode: '1000', currency: 'INR',\r\n            purchaseOrder: po1002, grossAmount: 121540, netAmount: 103000, taxAmount: 18540,\r\n            invoiceDate: new GlideDateTime().getDate(),\r\n            seedExtraction: { invoiceNumber: 'INV-BC-1002', vendor: 'V002', amount: 121540, invoice_date: todayStr2, posting_date: todayStr2 },\r\n            lines: [this._seedLine('PO-BC-1002', 'RCPT-BC-1002', 10, 10300, 18540, 103000)]\r\n        });\r\n        results['AP-BC-1002'] = { apInvoiceSysId: apBc1002.apInvoiceSysId, stoppedAt: apBc1002.stoppedAt };\r\n\r\n        // --- CASH-BC-0001: Exact match ------------------------------------------\r\n        var dueDate1 = new GlideDateTime();\r\n        dueDate1.addDaysUTC(30);\r\n        this._insert('x_695068_bcfa_ar_open_item', {\r\n            item_number: 'ARI-BC-0001', customer: customer001, company_code: '1000', currency: 'INR',\r\n            invoice_amount: 100000, open_amount: 100000, due_date: dueDate1.getDate(), status: 'open'\r\n        });\r\n        var cashBc0001 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'BANK-BC-0001', customer: customer001, currency: 'INR', amount: 100000, bankAccount: 'IN-COLL-BC-001',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-BC-0001'\r\n        });\r\n        results['CASH-BC-0001'] = cashBc0001;\r\n\r\n        // --- CASH-BC-0002: Short pay (paid 2500 less than the open item) -------\r\n        // Due date deliberately much older than any pre-existing open item\r\n        // for this customer (e.g. ARI0006) — multiInvoiceSuggestion greedily\r\n        // accumulates oldest-due-first until the running total reaches the\r\n        // payment amount, so this item must sort first or the demo's clean\r\n        // single-item short-pay picks up an extra unrelated item too.\r\n        var dueDate2 = new GlideDateTime();\r\n        dueDate2.addDaysUTC(-100);\r\n        this._insert('x_695068_bcfa_ar_open_item', {\r\n            item_number: 'ARI-BC-0002', customer: customer004, company_code: '1000', currency: 'EUR',\r\n            invoice_amount: 100000, open_amount: 100000, due_date: dueDate2.getDate(), status: 'open'\r\n        });\r\n        var cashBc0002 = this.arService.intakeAndAutoProcess({\r\n            bankReference: 'UTR20260917002', customer: customer004, currency: 'EUR', amount: 97500, bankAccount: 'DE-COLL-BC-002',\r\n            idempotencyKey: 'AR-CLEAR-DEMO-BC-0002'\r\n        });\r\n        results['CASH-BC-0002'] = cashBc0002;\r\n\r\n        return results;\r\n    },\r\n\r\n    // ---- Demo reset (Phase 28) ---------------------------------------------\r\n\r\n    // Puts the application's data back to the seeded demo baseline:\r\n    //   deletes  every AP invoice and payment with their lines, extractions,\r\n    //            matches, exceptions, approvals, remittances, match\r\n    //            candidates, allocations and deductions; integration\r\n    //            transactions; document intakes (with attachments); finance\r\n    //            exceptions; KPI rows; and master rows outside the seeded\r\n    //            baseline (POs, PO lines, receipts, open items, credit notes\r\n    //            not in seedMasterData, e.g. test data)\r\n    //   keeps    vendors, customers, aliases, integration profiles,\r\n    //            reference mappings (configuration); the audit trail\r\n    //            (append-only) and the decision log; the AI Interaction Log\r\n    //            unless x_695068_bcfa.demo.reset_clears_ai_log = true\r\n    // then seedAll() restores the master data values and re-runs the 10 AP\r\n    // and 10 AR scenarios. The reset itself is audited.\r\n    //\r\n    // Refused unless confirm is exactly DemoDataSeeder.RESET_CONFIRMATION and\r\n    // x_695068_bcfa.demo.reset_enabled is true (set it to false on any\r\n    // instance whose data must never be reset).\r\n    resetAndReseed: function(confirm) {\r\n        var reset = this.resetDemoData(confirm);\r\n        if (reset.refused) return reset;\r\n        return { reset: reset, seed: this.seedAll() };\r\n    },\r\n\r\n    resetDemoData: function(confirm) {\r\n        if (confirm !== DemoDataSeeder.RESET_CONFIRMATION) return { refused: true, reason: 'Pass the confirmation text \"' + DemoDataSeeder.RESET_CONFIRMATION + '\".' };\r\n        if (gs.getProperty('x_695068_bcfa.demo.reset_enabled', 'false') !== 'true') return { refused: true, reason: 'x_695068_bcfa.demo.reset_enabled is not true on this instance.' };\r\n\r\n        var deleted = {};\r\n        var wipe = function(table, query) {\r\n            var gr = new GlideRecord(table);\r\n            if (query) gr.addEncodedQuery(query);\r\n            gr.query();\r\n            var n = gr.getRowCount();\r\n            if (n) {\r\n                gr.setWorkflow(false);\r\n                gr.deleteMultiple();\r\n            }\r\n            deleted[table.replace('x_695068_bcfa_', '')] = n;\r\n        };\r\n\r\n        // Document intakes: attachments first.\r\n        var intake = new GlideRecord('x_695068_bcfa_finance_intake');\r\n        intake.query();\r\n        var attachments = new GlideSysAttachment();\r\n        while (intake.next()) attachments.deleteAll(intake);\r\n\r\n        // Children before parents.\r\n        ['x_695068_bcfa_ap_match', 'x_695068_bcfa_ap_extraction', 'x_695068_bcfa_ap_invoice_line', 'x_695068_bcfa_ap_approval',\r\n            'x_695068_bcfa_ap_exception', 'x_695068_bcfa_ap_invoice',\r\n            'x_695068_bcfa_match_candidate', 'x_695068_bcfa_deduction', 'x_695068_bcfa_payment_allocation', 'x_695068_bcfa_remittance',\r\n            'x_695068_bcfa_ar_approval', 'x_695068_bcfa_ar_exception', 'x_695068_bcfa_payment',\r\n            'x_695068_bcfa_integration_txn', 'x_695068_bcfa_finance_intake', 'x_695068_bcfa_finance_exception', 'x_695068_bcfa_kpi'\r\n        ].forEach(function(t) { wipe(t); });\r\n        if (gs.getProperty('x_695068_bcfa.demo.reset_clears_ai_log', 'false') === 'true') wipe('x_695068_bcfa_ai_interaction');\r\n\r\n        // Master rows outside the seeded baseline (test data).\r\n        var codes = function(prefix, n, width) {\r\n            var list = [];\r\n            for (var i = 1; i <= n; i++) list.push(prefix + ('000' + i).slice(-width));\r\n            return list.join(',');\r\n        };\r\n        wipe('x_695068_bcfa_receipt', 'receipt_numberNOT IN' + codes('RCPT', 10, 4));\r\n        wipe('x_695068_bcfa_po_line', 'purchase_order.po_numberNOT IN' + codes('PO', 10, 4) + '^ORpurchase_orderISEMPTY');\r\n        wipe('x_695068_bcfa_purchase_order', 'po_numberNOT IN' + codes('PO', 10, 4));\r\n        wipe('x_695068_bcfa_ar_open_item', 'item_numberNOT IN' + codes('ARI', 15, 4));\r\n        wipe('x_695068_bcfa_credit_note', 'credit_note_numberNOT IN' + codes('CN', 5, 4));\r\n\r\n        new AuditEngine().logEvent({\r\n            sourceTable: 'x_695068_bcfa_ap_invoice',\r\n            process: 'platform',\r\n            eventType: 'closure',\r\n            actorType: 'user',\r\n            description: 'Demo data reset: operational data deleted, master data back to the seeded baseline (audit trail kept).',\r\n            afterValue: { reset: 'demo_data', deleted: deleted }\r\n        });\r\n        return { deleted: deleted };\r\n    },\r\n\r\n    type: 'DemoDataSeeder'\r\n};\r\n\r\nDemoDataSeeder.RESET_CONFIRMATION = 'RESET BCFA DEMO DATA';\r\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/DemoDataSeeder.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/DemoDataSeeder.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_properties_28f9cc7ed7c744d88eddf954d5be35bf.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_properties\">\n  <sys_properties action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>28f9cc7ed7c744d88eddf954d5be35bf</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_properties_28f9cc7ed7c744d88eddf954d5be35bf</sys_update_name>\n    <choices/>\n    <description>false (default) = a demo reset keeps the AI Interaction Log as governance evidence (the AI KPIs then include earlier runs); true = the reset also clears it, for a clean dashboard. The audit trail is never cleared.</description>\n    <ignore_cache>false</ignore_cache>\n    <is_private>false</is_private>\n    <name>x_695068_bcfa.demo.reset_clears_ai_log</name>\n    <read_roles/>\n    <suffix>demo.reset_clears_ai_log</suffix>\n    <type>boolean</type>\n    <value>false</value>\n    <write_roles/>\n  </sys_properties>\n</record_update>"},{"name":"sys_properties_c9394f9a4c514aee9e58369e9b3d7546.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_properties\">\n  <sys_properties action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>c9394f9a4c514aee9e58369e9b3d7546</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_properties_c9394f9a4c514aee9e58369e9b3d7546</sys_update_name>\n    <choices/>\n    <description>true = DemoDataSeeder.resetDemoData may delete this instance's AP/AR operational data and restore the seeded demo baseline (POC demo instance). Set to false on any instance whose data must never be reset.</description>\n    <ignore_cache>false</ignore_cache>\n    <is_private>false</is_private>\n    <name>x_695068_bcfa.demo.reset_enabled</name>\n    <read_roles/>\n    <suffix>demo.reset_enabled</suffix>\n    <type>boolean</type>\n    <value>true</value>\n    <write_roles/>\n  </sys_properties>\n</record_update>"}];
var columns = [];
var docs = [];
var out = [];
if (gs.getCurrentScopeName() !== 'rhino.global') {
  gs.info('BCFA_DEPLOY ABORTED: run in scope "global", current scope is ' + gs.getCurrentScopeName());
} else {
  var gum = new GlideUpdateManager2();
  var added = 0, present = 0, colFailed = [];
  // Columns first, so choice sets and UI that reference them load cleanly.
  columns.forEach(function(c) {
    if (new GlideRecord(c.table).isValidField(c.element)) { present++; return; }
    var d = new GlideRecord('sys_dictionary');
    d.initialize();
    d.setNewGuidValue(c.sysId);
    for (var k in c.fields) d.setValue(k, c.fields[k]);
    d.setValue('sys_package', '229ba2b1a079431e104010f5ea883e85');
    d.insert();
    if (new GlideRecord(c.table).isValidField(c.element)) added++; else colFailed.push(c.element);
  });
  // Column labels with their build sys_ids; drop the duplicate label the
  // dictionary insert created.
  var docOk = 0;
  docs.forEach(function(f) {
    try { gum.loadXML(f.xml); docOk++; } catch (e) { out.push('FAILED ' + f.name + ': ' + e); }
    var id = (f.xml.match(/<sys_id>([0-9a-f]{32})<\/sys_id>/) || [])[1];
    var el = (f.xml.match(/<element>([^<]*)<\/element>/) || [])[1];
    var tbl = (f.xml.match(/<name>([^<]*)<\/name>/) || [])[1];
    var extra = new GlideRecord('sys_documentation');
    extra.addQuery('name', tbl);
    extra.addQuery('element', el);
    extra.addQuery('language', 'en');
    extra.addQuery('sys_id', '!=', id);
    extra.query();
    while (extra.next()) extra.deleteRecord();
  });
  var ok = 0, failed = 0;
  files.forEach(function(f) {
    try { gum.loadXML(f.xml); ok++; }
    catch (e) { failed++; out.push('FAILED ' + f.name + ': ' + e); }
  });
  // Records inserted from global scope carry the global package: give them
  // the application's package.
  var owned = [["sys_script_include","5557c39b046b40dbb32c511181f09e80"],["sys_module","27d2fb84df4d47d487c59705a63fe43b"],["sys_properties","28f9cc7ed7c744d88eddf954d5be35bf"],["sys_properties","c9394f9a4c514aee9e58369e9b3d7546"]];
  var packaged = 0;
  owned.forEach(function(o) {
    var rec = new GlideRecord(o[0]);
    if (!rec.isValid() || !rec.get(o[1])) return;
    if (rec.getValue('sys_scope') !== '229ba2b1a079431e104010f5ea883e85' || rec.getValue('sys_package') === '229ba2b1a079431e104010f5ea883e85') return;
    rec.setValue('sys_package', '229ba2b1a079431e104010f5ea883e85');
    rec.setWorkflow(false);
    rec.update();
    packaged++;
  });
  out.unshift('columns added=' + added + ' already present=' + present + (colFailed.length ? ' NOT CREATED: ' + colFailed.join(',') : '') +
    ' | labels=' + docOk + ' | records loaded=' + ok + ' failed=' + failed + ' of ' + files.length + ' | moved to the app package=' + packaged);
}
gs.info('BCFA_DEPLOY ' + out.join(' | '));
